"use strict";
/* 労災保険法 追加問題(X2/XT2/XS2)。ID恒久。 */
(window.QPARTS = window.QPARTS || []).push(
{id:"X2-001",s:2,q:"労災保険は、業務災害・複数業務要因災害・通勤災害に関する保険給付のほか、二次健康診断等給付を行い、あわせて社会復帰促進等事業を行うことができる。",a:true,e:"7条1項で保険給付は業務災害・複数業務要因災害・通勤災害・二次健康診断等給付の4種。2条の2で社会復帰促進等事業も行える。",topic:"目的・保険給付の種類"},
{id:"X2-002",s:2,q:"社会復帰促進等事業のうち一部は、独立行政法人高齢・障害・求職者雇用支援機構に行わせるものとされている。",a:false,e:"29条3項。社会復帰促進等事業の一部を行わせるのは独立行政法人労働者健康安全機構(労災病院の設置運営等)。",topic:"社会復帰促進等事業"},
{id:"X2-003",s:2,q:"国の直営事業にも、労災保険法が適用される。",a:false,e:"3条2項。国の直営事業及び官公署の事業(労基法別表第1に掲げる事業を除く)には労災保険法は適用されない。",topic:"適用事業"},
{id:"X2-004",s:2,q:"地方公務員については、現業部門の非常勤職員であっても、労災保険法が適用されることはない。",a:false,e:"3条2項の除外は官公署の事業(労基法別表第1の事業を除く)。地方公務員災害補償法の適用を受けない現業の非常勤職員には労災保険法が適用される。",topic:"適用事業"},
{id:"X2-005",s:2,q:"船員法上の船員を使用する事業にも、労災保険法が適用される。",a:true,e:"3条1項。平成22年の船員保険制度の統合により、船員の職務上災害・通勤災害も労災保険の対象となっている。",topic:"適用事業"},
{id:"X2-006",s:2,q:"暫定任意適用事業の事業主は、その事業に使用される労働者の3分の2以上が希望するときは、労災保険の加入の申請をしなければならない。",a:false,e:"整備法5条。加入申請が義務となるのは労働者の過半数が希望するとき。3分の2ではない。",topic:"暫定任意適用事業"},
{id:"X2-007",s:2,q:"暫定任意適用事業の保険関係の消滅は、事業主の申請があれば、労働者の同意を要することなく認可される。",a:false,e:"整備法8条。保険関係成立後1年以上経過し、かつ労働者の過半数の同意を得て申請し、認可を受ける必要がある。",topic:"暫定任意適用事業"},
{id:"X2-008",s:2,q:"労働者派遣事業による派遣労働者に係る労災保険の適用事業は、派遣先の事業である。",a:false,e:"派遣労働者の労災保険は、派遣元事業主の事業が適用事業となる(通達)。保険料も派遣元が負担する。",topic:"適用・労働者性"},
{id:"X2-009",s:2,q:"株式会社の取締役は、業務執行権の有無にかかわらず、労災保険法上の労働者として扱われることはない。",a:false,e:"通達。業務執行権がなく、代表者の指揮命令を受けて労働し賃金を得ている取締役は労働者として扱われる。",topic:"適用・労働者性"},
{id:"X2-010",s:2,q:"法人の代表取締役は労働者に該当しないため、中小事業主等として特別加入しなければ労災保険の保護を受けることができない。",a:true,e:"労働者は労基法9条と同義。代表者は労働者でないため、33条1号の中小事業主等の特別加入によって保護を受ける。",topic:"適用・労働者性"},
{id:"X2-011",s:2,q:"同居の親族のみを使用する事業において、その同居の親族は、原則として労災保険法上の労働者に該当しない。",a:true,e:"労基法116条2項で同居の親族のみを使用する事業は労基法の適用除外。労災保険法上の労働者にも原則該当しない。",topic:"適用・労働者性"},
{id:"X2-012",s:2,q:"在籍型出向の労働者が、出向先の指揮監督の下で出向先の業務に従事している場合、その者の労災保険関係は出向先の事業にあるものとして扱われる。",a:true,e:"通達。出向先と実質的な労働関係があり、出向先の指揮監督下で労働する場合は、出向先の事業の保険関係による。",topic:"適用・労働者性"},
{id:"X2-013",s:2,q:"自己所有のトラックを持ち込み、特定の会社の製品運送に従事する運転手は、業務遂行上の指揮監督の程度が緩やかであっても、常に労災保険法上の労働者に該当する。",a:false,e:"旭紙業事件(最判平8.11.28)は、指揮監督の程度・報酬の性格等から、持込み運転手は労働者に当たらないとした。",topic:"適用・労働者性"},
{id:"X2-014",s:2,q:"サービス業を営む事業主が中小事業主等として特別加入できるのは、常時50人以下の労働者を使用する場合である。",a:false,e:"33条1号・則46条の16。卸売・サービス業は常時100人以下。50人以下は金融・保険・不動産・小売業。",topic:"特別加入"},
{id:"X2-015",s:2,q:"小売業を営む事業主が中小事業主等として特別加入できるのは、常時300人以下の労働者を使用する場合である。",a:false,e:"則46条の16。小売業は金融・保険・不動産業と同じく常時50人以下。300人以下は原則(下記以外の業種)の基準。",topic:"特別加入"},
{id:"X2-016",s:2,q:"中小事業主が特別加入する場合、原則として、その事業に従事する家族従事者や労働者以外の役員も包括して加入させる必要がある。",a:true,e:"34条・通達。中小事業主の特別加入は、事業主本人と業務に従事する家族従事者・役員を包括して行うのが原則。",topic:"特別加入"},
{id:"X2-017",s:2,q:"中小事業主等の特別加入は、労働者を使用しないで事業を行う事業主であっても行うことができる。",a:false,e:"33条1号は労働者を使用する中小事業主が対象。労働者を使用しない者は一人親方等(33条3号)として特別加入する。",topic:"特別加入"},
{id:"X2-018",s:2,q:"特別加入者にも、一般の労働者と同様に二次健康診断等給付が行われる。",a:false,e:"34条等。特別加入者は安衛法の定期健康診断(一次健康診断)の対象外であり、二次健康診断等給付は行われない。",topic:"特別加入"},
{id:"X2-019",s:2,q:"特別加入者の休業(補償)等給付は、所得喪失の有無にかかわらず、療養のため補償の対象とされる範囲の業務に全部従事できないことが支給要件となる。",a:true,e:"通達。特別加入者には賃金を受けない日という要件はなく、全部労働不能であることが休業の要件とされる。",topic:"特別加入"},
{id:"X2-020",s:2,q:"特別加入者にも、特別給与を算定基礎とする障害特別年金や遺族特別年金などのボーナス特別支給金が支給される。",a:false,e:"特別支給金支給規則。特別加入者には一般の特別支給金は支給されるが、特別給与を基礎とするボーナス特別支給金は支給されない。",topic:"特別加入"},
{id:"X2-021",s:2,q:"海外派遣者の特別加入は、国内の有期事業から海外の事業に派遣される者も対象となる。",a:false,e:"33条7号。海外派遣者は日本国内で行われる事業(有期事業を除く)から派遣される者に限られる。",topic:"特別加入"},
{id:"X2-022",s:2,q:"海外の現地法人が現地で直接採用した者も、海外派遣者として特別加入することができる。",a:false,e:"33条7号。海外派遣者は国内の事業から派遣される者に限られ、現地採用者は対象外。",topic:"特別加入"},
{id:"X2-023",s:2,q:"海外派遣者として特別加入した者には、通勤災害に関する保険給付も行われる。",a:true,e:"36条。海外派遣者の特別加入は業務災害・通勤災害ともに保護される(通勤災害の対象外は個人タクシー業者等の一部の一人親方等)。",topic:"特別加入"},
{id:"X2-024",s:2,q:"特別加入者が保険料を滞納している期間中に生じた事故については、政府は保険給付の全部又は一部を行わないことができる。",a:true,e:"34条1項4号・35条・36条。特別加入保険料の滞納期間中の事故は、保険給付の全部又は一部を行わないことができる。",topic:"特別加入"},
{id:"X2-025",s:2,q:"企業等から業務委託を受けて事業を行う特定受託事業者(いわゆるフリーランス)は、2024年11月から特別加入の対象とされている(2026年4月時点)。",a:true,e:"33条・施行規則。フリーランス法の施行(2024年11月1日)にあわせ、特定受託事業者が特別加入できるようになった。",topic:"特別加入"},
{id:"X2-026",s:2,q:"家事支援従事者は、特別加入の対象とされていない。",a:false,e:"33条5号・則。家事支援従事者は介護作業従事者等と並び特定作業従事者として特別加入できる。",topic:"特別加入"},
{id:"X2-027",s:2,q:"労働者を使用する者は、その使用が年間100日未満の見込みであっても、一人親方等として特別加入することはできない。",a:false,e:"通達。労働者を使用する場合でも、その使用が年間100日に満たないと見込まれるときは一人親方等として特別加入できる。",topic:"特別加入"},
{id:"X2-028",s:2,q:"業務災害と認められるためには、原則として、業務遂行性と業務起因性の双方が認められることが必要である。",a:true,e:"7条1項1号・通達。事業主の支配下にある状態(業務遂行性)と、業務と傷病等の相当因果関係(業務起因性)が要件。",topic:"業務災害の認定"},
{id:"X2-029",s:2,q:"地震などの天災地変による被災は、業務の性質上危険な環境下で作業していたと認められる場合であっても、業務上とされることはない。",a:false,e:"通達。天災地変は原則業務外だが、作業条件・環境等から天災地変に際して災害を被りやすい事情があれば業務上とされる。",topic:"業務災害の認定"},
{id:"X2-030",s:2,q:"休憩時間中に事業場施設内でキャッチボールをしていて負傷した場合、休憩中も事業主の支配下にあるため、原則として業務上の災害となる。",a:false,e:"通達。休憩中の私的行為による災害は原則業務外。施設・設備の欠陥等に起因する場合に限り業務上となる。",topic:"業務災害の認定"},
{id:"X2-031",s:2,q:"事業主の命令により、業務として運動競技会に出場している間の負傷は、業務上の災害となりうる。",a:true,e:"通達。事業主の命令で業務として出場し、出張・出勤扱いである等の場合は業務遂行性が認められる。",topic:"業務災害の認定"},
{id:"X2-032",s:2,q:"他人の故意による暴行で負傷した場合であっても、その暴行が業務に内在する危険が現実化したものと認められるときは、業務上とされる。",a:true,e:"通達。私的怨恨や本人の挑発による場合を除き、業務に内在・随伴する危険の現実化と認められれば業務上。",topic:"業務災害の認定"},
{id:"X2-033",s:2,q:"労働基準法施行規則別表第1の2に具体的に列挙されていない疾病は、業務に起因することが明らかであっても業務上の疾病とはされない。",a:false,e:"労基則別表第1の2第11号「その他業務に起因することの明らかな疾病」により、列挙外でも業務上とされうる。",topic:"業務上の疾病"},
{id:"X2-034",s:2,q:"脳・心臓疾患の認定基準では、発症前1か月間におおむね80時間を超える時間外労働があれば、それだけで業務と発症との関連性が強いと評価される。",a:false,e:"令和3年認定基準。強いと評価されるのは発症前1か月おおむね100時間超、又は2〜6か月平均おおむね80時間超。",topic:"業務上の疾病"},
{id:"X2-035",s:2,q:"脳・心臓疾患の認定基準では、発症前2か月間ないし6か月間にわたり1か月当たりおおむね45時間を超える時間外労働があれば、それだけで業務との関連性が強いと評価される。",a:false,e:"令和3年認定基準。強いと評価されるのは2〜6か月平均おおむね80時間超。45時間超は長くなるほど関連性が徐々に強まる水準。",topic:"業務上の疾病"},
{id:"X2-036",s:2,q:"精神障害の労災認定では、対象疾病の発病前おおむね1年の間に業務による強い心理的負荷が認められることが要件の一つとされている。",a:false,e:"令和5年認定基準。評価期間は発病前おおむね6か月。1年ではない。",topic:"業務上の疾病"},
{id:"X2-037",s:2,q:"精神障害の認定基準では、顧客や取引先等から著しい迷惑行為を受けたこと(いわゆるカスタマーハラスメント)も、業務による心理的負荷の具体的出来事として評価の対象とされている(2026年4月時点)。",a:true,e:"令和5年9月改正の認定基準で、顧客や取引先、施設利用者等からの著しい迷惑行為が具体的出来事に追加された。",topic:"業務上の疾病"},
{id:"X2-038",s:2,q:"業務による精神障害によって正常な認識や行為選択能力が著しく阻害された状態で自殺した場合は、故意による死亡とされ、遺族(補償)等給付は支給されない。",a:false,e:"12条の2の2第1項・通達。業務による精神障害で判断能力が著しく阻害された状態での自殺は、故意には該当しない。",topic:"支給制限"},
{id:"X2-039",s:2,q:"事業主が提供する専用の通勤バスを利用して出勤する途中の事故は、通勤災害として取り扱われる。",a:false,e:"7条2項。事業主提供の専用交通機関による出退勤は業務の性質を有するため通勤から除かれ、業務災害として扱われる。",topic:"通勤の定義"},
{id:"X2-040",s:2,q:"休日に突発的事故の対応のため緊急に呼び出され、会社に向かう途中で被災した場合は、業務災害として取り扱われる。",a:true,e:"7条2項・通達。緊急用務のための休日呼出しによる出勤は業務の性質を有し、通勤ではなく業務災害となる。",topic:"通勤の定義"},
{id:"X2-041",s:2,q:"転任に伴い配偶者と別居して単身赴任している労働者が、赴任先住居と帰省先住居との間を移動する場合も、一定の要件を満たせば通勤に該当する。",a:true,e:"7条2項3号・則7条。住居と就業場所の往復に先行・後続する住居間の移動は、要件を満たせば通勤。",topic:"通勤の定義"},
{id:"X2-042",s:2,q:"単身赴任者が帰省先住居から赴任先住居へ移動する場合、原則として、業務に従事する当日又はその翌日に行われるものであれば通勤に該当しうる。",a:false,e:"7条2項3号・通達。帰省先→赴任先は就業の当日又は前日。当日又は翌日は赴任先→帰省先の移動。",topic:"通勤の定義"},
{id:"X2-043",s:2,q:"通勤の途中で経路近くの公衆トイレを使用する程度のささいな行為は、逸脱・中断に当たらない。",a:true,e:"7条3項・通達。経路上の売店でタバコを買う、公衆トイレを使う等のささいな行為は逸脱・中断として扱わない。",topic:"逸脱・中断"},
{id:"X2-044",s:2,q:"退勤の途中で映画館に立ち寄って映画を観た後、合理的な経路に復帰して帰宅する途中に被災した場合、復帰後の移動は通勤と認められる。",a:false,e:"7条3項・則8条。映画鑑賞は日常生活上必要な行為に当たらないため、逸脱後の移動は復帰しても通勤とならない。",topic:"逸脱・中断"},
{id:"X2-045",s:2,q:"退勤の途中で病院に立ち寄って診察を受けた場合、合理的な経路に復した後の移動は通勤と認められる。",a:true,e:"7条3項・則8条4号。病院又は診療所で診察・治療を受ける行為は日常生活上必要な行為。復帰後は通勤となる。",topic:"逸脱・中断"},
{id:"X2-046",s:2,q:"選挙権の行使その他これに準ずる行為は、逸脱・中断の例外となる日常生活上必要な行為とされている。",a:true,e:"則8条3号。選挙権の行使等は日常生活上必要な行為として定められている。",topic:"逸脱・中断"},
{id:"X2-047",s:2,q:"要介護状態にある父母の介護は、継続的に又は反復して行われるものであれば、逸脱・中断の例外となる日常生活上必要な行為に該当する。",a:true,e:"則8条5号。要介護状態の配偶者・子・父母・孫・祖父母・兄弟姉妹・配偶者の父母の介護(継続的又は反復)。",topic:"逸脱・中断"},
{id:"X2-048",s:2,q:"要介護状態にある配偶者の父母の介護は、逸脱・中断の例外となる日常生活上必要な行為に含まれない。",a:false,e:"則8条5号。配偶者の父母も介護の対象家族に含まれる(継続的又は反復して行われるものに限る)。",topic:"逸脱・中断"},
{id:"X2-049",s:2,q:"学校教育法第1条の学校において行われる教育であって職業能力の開発向上に資するものを受ける行為は、日常生活上必要な行為に含まれる。",a:true,e:"則8条2号。職業訓練、学校教育法1条の学校での教育その他これに準ずる教育訓練で職業能力の開発向上に資するもの。",topic:"逸脱・中断"},
{id:"X2-050",s:2,q:"大雪などの交通事情で翌日の出勤に備えて会社近くのホテルに宿泊した場合、そのホテルから出勤する途中の事故は、通勤災害となりうる。",a:true,e:"7条2項・通達。やむを得ない事情で就業のため一時的に宿泊する場所も住居として扱われる。",topic:"通勤の定義"},
{id:"X2-051",s:2,q:"所定の就業開始時刻とかけ離れた時刻に出勤するなど、就業との関連性が認められない往復は、通勤に該当しない。",a:true,e:"7条2項「就業に関し」。業務に就くため又は業務を終えたことにより行われる移動であることが必要。",topic:"通勤の定義"},
{id:"X2-052",s:2,q:"住居と就業の場所との間に合理的な経路が複数ある場合、そのうち最短の経路のみが合理的な経路とされる。",a:false,e:"7条2項・通達。通常利用しうる経路が複数あれば、いずれも合理的な経路となる。最短経路に限られない。",topic:"通勤の定義"},
{id:"X2-053",s:2,q:"マイカー通勤者が道路工事のため迂回路を通行した場合、その迂回路は届け出た経路と異なるため合理的な経路とならない。",a:false,e:"7条2項・通達。道路工事等でやむを得ず迂回する経路も合理的な経路とされる。",topic:"通勤の定義"},
{id:"X2-054",s:2,q:"泥酔しての自動車運転による移動は、通勤における合理的な方法とは認められない。",a:true,e:"7条2項・通達。無免許運転や泥酔運転など、通常とられない方法による移動は合理的な方法と認められない。",topic:"通勤の定義"},
{id:"X2-055",s:2,q:"特別加入した中小事業主等には、通勤災害に関する保険給付は行われない。",a:false,e:"34条・35条。中小事業主等には通勤災害の給付も行われる。対象外は個人タクシー業者や自営漁業者等の一部の一人親方等。",topic:"特別加入"},
{id:"X2-056",s:2,q:"外回りの営業担当者が、会社の指示で自宅から直接最初の得意先に向かう場合、その得意先が就業の場所となり、その移動は通勤となりうる。",a:true,e:"7条2項・通達。就業の場所とは業務を開始・終了する場所で、得意先等への直行直帰の場合はその得意先が就業の場所となる。",topic:"通勤の定義"},
{id:"X2-057",s:2,q:"複数就業者が一の事業場から他の事業場へ移動する間に被災した場合、その通勤災害の保険関係は、移動元の事業場に係るものとして処理される。",a:false,e:"7条2項2号・通達。事業場間移動は移動先の事業場で労務提供のために行うものであり、移動先の事業場の保険関係で処理される。",topic:"通勤の定義"},
{id:"X2-058",s:2,q:"給付基礎日額の算定事由発生日は、負傷若しくは死亡の原因である事故が発生した日、又は診断によって疾病の発生が確定した日である。",a:true,e:"8条1項。平均賃金を算定すべき事由の発生日は、事故発生日又は診断により疾病発生が確定した日とされる。",topic:"給付基礎日額"},
{id:"X2-059",s:2,q:"給付基礎日額に1円未満の端数があるときは、これを切り捨てる。",a:false,e:"8条の5。給付基礎日額に1円未満の端数があるときは1円に切り上げる。",topic:"給付基礎日額"},
{id:"X2-060",s:2,q:"平均賃金の算定期間中に業務外の傷病による休業期間がある場合、その期間の日数と賃金を控除して算定した額が平均賃金相当額を超えるときは、控除後の額が給付基礎日額となる。",a:true,e:"8条2項・則9条1項1号。私傷病休業期間を控除して算定した方が高ければ、その額を給付基礎日額とする。",topic:"給付基礎日額"},
{id:"X2-061",s:2,q:"平均賃金相当額を給付基礎日額とすることが適当でないと認められるときは、厚生労働省令で定めるところにより政府が算定する額を給付基礎日額とする。",a:true,e:"8条2項。平均賃金相当額が不適当な場合は、則9条等に基づき政府が算定する。",topic:"給付基礎日額"},
{id:"X2-062",s:2,q:"平均賃金相当額が自動変更対象額に満たない場合には、自動変更対象額が給付基礎日額とされる。",a:true,e:"8条2項・則9条1項。給付基礎日額の最低保障として自動変更対象額(毎年8月1日改定)が用いられる。",topic:"給付基礎日額"},
{id:"X2-063",s:2,q:"雇入れ後3か月に満たない者の給付基礎日額(平均賃金相当額)は、雇入れ後の期間について算定する。",a:true,e:"8条1項・労基法12条6項。雇入れ後3か月未満の者は雇入れ後の期間と賃金総額で平均賃金を算定する。",topic:"給付基礎日額"},
{id:"X2-064",s:2,q:"休業給付基礎日額のスライド改定は、平均給与額が100分の110を超え又は100分の90を下回った四半期の翌四半期の初日以後に支給すべき事由が生じた休業(補償)等給付から行われる。",a:false,e:"8条の2第1項2号。改定は変動した四半期の翌々四半期の初日以後の分から。",topic:"スライド"},
{id:"X2-065",s:2,q:"年金給付基礎日額のスライド改定は、年度の平均給与額の変動が100分の10を超える場合に限り行われる。",a:false,e:"8条の3第1項。年金は完全自動賃金スライドで変動幅の要件はない。10%要件は休業給付基礎日額の四半期スライド。",topic:"スライド"},
{id:"X2-066",s:2,q:"年金給付基礎日額のスライド改定は、算定事由発生日の属する年度の翌年度の4月以後の分から適用される。",a:false,e:"8条の3第1項2号。算定事由発生日の属する年度の翌々年度の8月以後の分から改定される。",topic:"スライド"},
{id:"X2-067",s:2,q:"年金給付基礎日額には、年金の支給開始当初から年齢階層別の最低・最高限度額が適用される。",a:true,e:"8条の3第2項。休業は療養開始後1年6か月経過後から適用だが、年金は支給当初から適用される。",topic:"年齢階層別限度額"},
{id:"X2-068",s:2,q:"障害(補償)等一時金などの一時金の給付基礎日額にも、年金と同様に年齢階層別の最低・最高限度額が適用される。",a:false,e:"8条の4。一時金はスライド規定を準用するが、年齢階層別限度額は適用しない。",topic:"年齢階層別限度額"},
{id:"X2-069",s:2,q:"年金給付基礎日額に係る年齢階層別限度額の適用にあたっての年齢は、支給すべき月の属する年度の8月1日における年齢による。",a:true,e:"8条の3第2項。年金は各年度の8月1日における年齢の階層で限度額を適用する。",topic:"年齢階層別限度額"},
{id:"X2-070",s:2,q:"休業給付基礎日額に係る年齢階層別限度額の適用にあたっての年齢は、休業の初日における年齢による。",a:false,e:"8条の2第2項。休業は支給すべき事由が生じた日の属する四半期の初日における年齢による。",topic:"年齢階層別限度額"},
{id:"X2-071",s:2,q:"遺族(補償)等年金の年金給付基礎日額に年齢階層別限度額を適用する場合の年齢は、受給権者である遺族の年齢ではなく、死亡した労働者の年齢(生存していたと仮定した年齢)による。",a:true,e:"8条の3第2項。遺族(補償)等年金では、死亡した労働者が当該年度の8月1日に生存していたとした場合の年齢を用いる。",topic:"年齢階層別限度額"},
{id:"X2-072",s:2,q:"複数事業労働者の通勤災害に係る給付基礎日額は、被災時に向かっていた事業場の賃金のみを基礎として算定される。",a:false,e:"8条3項。複数事業労働者の通勤災害も、各事業の給付基礎日額相当額を合算して算定する。",topic:"給付基礎日額"},
{id:"X2-073",s:2,q:"療養の給付は、社会復帰促進等事業として設置された病院若しくは診療所又は都道府県労働局長の指定する病院等(指定病院等)において行われる。",a:true,e:"13条・則11条。療養の給付は労災病院等又は都道府県労働局長が指定する病院・診療所・薬局・訪問看護事業者で行う。",topic:"療養(補償)等給付"},
{id:"X2-074",s:2,q:"療養の費用の支給は、療養の給付をすることが困難な場合のほか、療養の給付を受けないことについて労働者に相当の理由がある場合に行われる。",a:true,e:"13条3項・則11条の2。療養の給付が原則で、困難な場合や相当の理由がある場合に療養の費用を支給する。",topic:"療養(補償)等給付"},
{id:"X2-075",s:2,q:"療養の給付の範囲には移送が含まれるが、居宅における療養上の管理及びその療養に伴う世話その他の看護は含まれない。",a:false,e:"13条2項。居宅における療養上の管理・看護(4号)も移送(6号)も療養の給付の範囲に含まれる。",topic:"療養(補償)等給付"},
{id:"X2-076",s:2,q:"傷病(補償)等年金が支給される者には、療養(補償)等給付は支給されない。",a:false,e:"18条2項で傷病(補償)等年金受給者に支給されないのは休業(補償)等給付。療養(補償)等給付は併せて支給される。",topic:"療養(補償)等給付"},
{id:"X2-077",s:2,q:"業務災害により療養の給付を受ける労働者は、一部負担金として200円を負担する。",a:false,e:"31条2項。一部負担金は通勤災害の療養給付を受ける者から徴収するもので、業務災害には一部負担金はない。",topic:"一部負担金"},
{id:"X2-078",s:2,q:"通勤災害の療養給付に係る一部負担金は、原則として、休業給付の額から控除することにより徴収される。",a:true,e:"31条2項・3項、則44条の2。一部負担金は最初に支給すべき休業給付の額から控除する方法で徴収する。",topic:"一部負担金"},
{id:"X2-079",s:2,q:"第三者の行為によって生じた通勤災害により療養給付を受ける者からは、一部負担金は徴収されない。",a:true,e:"則44条の2。第三者行為災害の者、休業給付を受けない者、既に一部負担金を納付した者、特別加入者等からは徴収しない。",topic:"一部負担金"},
{id:"X2-080",s:2,q:"健康保険の日雇特例被保険者である労働者が通勤災害で療養給付を受ける場合の一部負担金は、100円である。",a:true,e:"31条2項・則44条の2。一部負担金は200円、ただし日雇特例被保険者は100円。",topic:"一部負担金"},
{id:"X2-081",s:2,q:"療養の費用を請求する権利の時効は、療養を開始した日の翌日から一括して起算して2年である。",a:false,e:"42条・通達。療養の費用は、費用を支出した日ごとにその翌日から起算して2年。",topic:"時効"},
{id:"X2-082",s:2,q:"療養(補償)等給付は傷病が治ゆするまで行われるが、ここでいう治ゆとは、傷病が完全に元どおりに回復した状態をいう。",a:false,e:"通達。治ゆとは症状が安定し、医療効果が期待できなくなった状態(症状固定)をいい、完全回復を意味しない。",topic:"療養(補償)等給付"},
{id:"X2-083",s:2,q:"治ゆした後に同一の業務上の傷病が再発した場合には、再び療養(補償)等給付を受けることができる。",a:true,e:"通達。再発は原傷病と同一の傷病として扱われ、療養(補償)等給付等の対象となる。",topic:"療養(補償)等給付"},
{id:"X2-084",s:2,q:"指定病院等で療養の給付を受けようとする者は、療養の給付請求書を当該指定病院等を経由して所轄労働基準監督署長に提出する。",a:true,e:"則12条。療養の給付の請求書は、療養を受けようとする指定病院等を経由して所轄労働基準監督署長に提出する。",topic:"請求手続"},
{id:"X2-085",s:2,q:"所定労働時間の途中で被災し、その日の残りの時間を休業した場合、その日は待期期間の1日目に算入される。",a:true,e:"14条1項・通達。所定労働時間の一部を休業した被災当日も、休業日として待期3日に含まれる。",topic:"休業(補償)等給付"},
{id:"X2-086",s:2,q:"休業(補償)等給付の要件である賃金を受けない日には、平均賃金の100分の60未満の金額しか受けない日も含まれる。",a:true,e:"14条1項・通達。平均賃金の60%未満の金額しか支払われない日も賃金を受けない日として扱われる。",topic:"休業(補償)等給付"},
{id:"X2-087",s:2,q:"療養のため休業した日について年次有給休暇を取得して賃金を受けた場合でも、その日について休業(補償)等給付は支給される。",a:false,e:"14条1項。年休を取得し賃金を受けた日は賃金を受けない日に当たらず、休業(補償)等給付は支給されない。",topic:"休業(補償)等給付"},
{id:"X2-088",s:2,q:"休業(補償)等給付は、事業場の所定休日については、療養のため労働することができない場合であっても支給されない。",a:false,e:"14条1項・通達。所定休日であっても療養のため労働できず賃金を受けない日であれば支給される。",topic:"休業(補償)等給付"},
{id:"X2-089",s:2,q:"休業(補償)等給付の要件である労働することができないとは、必ずしも負傷前の業務に従事できないことをいうのではなく、一般に労働できない状態をいう。",a:true,e:"14条1項・通達。軽作業に就くことができても、療養のため一般的に労働不能であることを要件とする趣旨。",topic:"休業(補償)等給付"},
{id:"X2-090",s:2,q:"休業特別支給金の支給の申請は、休業した日の翌日から起算して5年以内に行えばよい。",a:false,e:"特別支給金支給規則3条。休業特別支給金の申請期限は2年。5年は障害・遺族・傷病特別支給金。",topic:"特別支給金"},
{id:"X2-091",s:2,q:"所定労働時間の一部について労働した日の休業特別支給金の額は、給付基礎日額から実際に支払われる賃金の額を控除した額の100分の20である。",a:true,e:"特別支給金支給規則3条。一部休業日は休業(補償)等給付と同様に、控除後の額の20%。",topic:"特別支給金"},
{id:"X2-092",s:2,q:"休業特別支給金は、休業(補償)等給付と異なり、休業の初日から支給される。",a:false,e:"特別支給金支給規則3条。休業特別支給金も待期3日を経過した第4日目から支給される。",topic:"特別支給金"},
{id:"X2-093",s:2,q:"労働基準法に規定する災害補償の事由について、労災保険法に基づき災害補償に相当する給付が行われるべき場合には、使用者は、労働基準法上の補償の責を免れる。",a:true,e:"労基法84条1項。労災保険法に基づき災害補償に相当する給付が行われるべき場合、使用者は補償の責を免れる。",topic:"労基法との関係"},
{id:"X2-094",s:2,q:"複数業務要因災害による休業の場合、待期期間の3日間については、各事業主が労働基準法上の休業補償を行わなければならない。",a:false,e:"複数業務要因災害は個々の事業主の災害補償責任の対象ではないため、待期3日の労基法上の休業補償義務もない。",topic:"複数業務要因災害"},
{id:"X2-095",s:2,q:"傷病(補償)等年金は、療養開始後1年6か月を経過した日に要件を満たさなくても、同日後に要件を満たすに至った場合には支給される。",a:true,e:"12条の8第3項。1年6か月経過日又は同日後に、治らず傷病等級に該当する状態であれば支給。",topic:"傷病(補償)等年金"},
{id:"X2-096",s:2,q:"傷病(補償)等年金の支給は、労働者の請求に基づいて行われる。",a:false,e:"12条の8第3項。傷病(補償)等年金は請求によらず、所轄労働基準監督署長の職権による支給決定で支給される。",topic:"傷病(補償)等年金"},
{id:"X2-097",s:2,q:"療養開始後1年6か月を経過した日において傷病が治っていない場合、労働者は、同日以後3か月以内に傷病の状態等に関する届を所轄労働基準監督署長に提出しなければならない。",a:false,e:"施行規則。届の提出期限は1年6か月経過日以後1か月以内。",topic:"傷病(補償)等年金"},
{id:"X2-098",s:2,q:"傷病等級第1級に該当する場合の傷病(補償)等年金の額は、給付基礎日額の277日分である。",a:false,e:"18条・別表第1。1級313日分、2級277日分、3級245日分。",topic:"傷病(補償)等年金"},
{id:"X2-099",s:2,q:"傷病等級第3級に該当する場合の傷病(補償)等年金の額は、給付基礎日額の277日分である。",a:false,e:"別表第1。3級は245日分。277日分は2級の額。",topic:"傷病(補償)等年金"},
{id:"X2-100",s:2,q:"傷病特別支給金の額は、傷病等級第1級の場合342万円である。",a:false,e:"特別支給金支給規則5条の2。傷病特別支給金1級は114万円。342万円は障害特別支給金1級。",topic:"特別支給金"},
{id:"X2-101",s:2,q:"傷病(補償)等年金の受給者の障害の程度が軽くなり、傷病等級に該当しなくなったときは、年金の支給は打ち切られ、要件を満たせば休業(補償)等給付が支給される。",a:true,e:"18条の2・通達。傷病等級に該当しなくなれば年金は終了し、療養のため休業していれば休業(補償)等給付が支給される。",topic:"傷病(補償)等年金"},
{id:"X2-102",s:2,q:"傷病(補償)等年金の受給権者は、請求により傷病(補償)等年金前払一時金を受けることができる。",a:false,e:"59条・60条。前払一時金の制度があるのは障害(補償)等年金と遺族(補償)等年金のみ。",topic:"前払一時金"},
{id:"X2-103",s:2,q:"傷病等級に該当する障害の程度は、3か月以上の期間にわたって存する障害の状態により認定される。",a:false,e:"則18条2項。傷病等級は6か月以上の期間にわたって存する障害の状態により認定する。",topic:"傷病(補償)等年金"},
{id:"X2-104",s:2,q:"障害等級第7級に該当する場合の障害(補償)等年金の額は、給付基礎日額の131日分である。",a:true,e:"15条・別表第1。年金は1級313・2級277・3級245・4級213・5級184・6級156・7級131日分。",topic:"障害(補償)等給付"},
{id:"X2-105",s:2,q:"障害等級第8級に該当する場合の障害(補償)等一時金の額は、給付基礎日額の391日分である。",a:false,e:"別表第2。8級は503日分。391日分は9級。",topic:"障害(補償)等給付"},
{id:"X2-106",s:2,q:"障害等級第14級に該当する場合の障害(補償)等一時金の額は、給付基礎日額の156日分である。",a:false,e:"別表第2。14級は56日分。156日分は6級の年金額・12級の一時金額。",topic:"障害(補償)等給付"},
{id:"X2-107",s:2,q:"障害等級第4級に該当する場合の障害(補償)等年金の額は、給付基礎日額の184日分である。",a:false,e:"別表第1。4級は213日分。184日分は5級。",topic:"障害(補償)等給付"},
{id:"X2-108",s:2,q:"障害特別支給金の額は、障害等級第1級の場合342万円、第14級の場合8万円である。",a:true,e:"特別支給金支給規則4条・別表第1。1級342万円〜14級8万円の一時金。",topic:"特別支給金"},
{id:"X2-109",s:2,q:"第5級以上に該当する身体障害が2以上ある場合には、重い方の障害等級を3級繰り上げる。",a:true,e:"則14条3項。13級以上2以上は1級、8級以上2以上は2級、5級以上2以上は3級繰上げ。",topic:"障害等級の併合"},
{id:"X2-110",s:2,q:"第8級以上に該当する身体障害が2以上ある場合には、重い方の障害等級を1級繰り上げる。",a:false,e:"則14条3項。8級以上が2以上なら2級繰上げ。1級繰上げは13級以上が2以上の場合。",topic:"障害等級の併合"},
{id:"X2-111",s:2,q:"第9級と第13級の障害を併合して第8級とする場合、その給付額は、第9級と第13級の一時金の合算額とされる。",a:true,e:"則14条3項ただし書。繰上げ後の8級(503日分)が9級391+13級101=492日分を超えるため、合算額が上限となる。",topic:"障害等級の併合"},
{id:"X2-112",s:2,q:"既存障害が第8級(一時金)であった者が加重により第7級(年金)となった場合、第7級の年金額から第8級の一時金の額をそのまま差し引いた額の年金が支給される。",a:false,e:"則14条5項。既存の一時金の額を25で除した額を年金額から差し引く。",topic:"加重障害"},
{id:"X2-113",s:2,q:"障害(補償)等年金差額一時金は、年金の受給権者が死亡した場合に、既に支給された年金と前払一時金の合計額が所定の額に満たないときに、その差額が遺族に支給されるものである。",a:true,e:"58条・附則。障害等級に応じた所定額(1級1,340日分〜7級560日分)との差額を遺族に支給。",topic:"差額一時金"},
{id:"X2-114",s:2,q:"障害等級第1級の障害(補償)等年金差額一時金の算定の基準となる額は、給付基礎日額の1,000日分である。",a:false,e:"58条・附則。1級は1,340日分。1,000日分は遺族(補償)等一時金・遺族の前払一時金上限。",topic:"差額一時金"},
{id:"X2-115",s:2,q:"障害(補償)等年金差額一時金を受けることができる遺族は、労働者の死亡当時その収入によって生計を維持していた者に限られる。",a:false,e:"58条。第1順位は死亡当時生計を同じくしていた配偶者・子・父母・孫・祖父母・兄弟姉妹、第2順位はそれ以外のこれらの者。生計維持要件はない。",topic:"差額一時金"},
{id:"X2-116",s:2,q:"障害(補償)等年金前払一時金の額は、障害等級に応じて定められた額のうちから受給権者が選択した額であり、第7級の最高額は給付基礎日額の560日分である。",a:true,e:"59条・附則。7級は200・400・560日分から選択。最高額は差額一時金の基準額と同じ。",topic:"前払一時金"},
{id:"X2-117",s:2,q:"障害(補償)等年金前払一時金は、年金の支給決定の通知のあった日の翌日から起算して2年を経過する日までの間であれば、年金の請求後に請求することができる。",a:false,e:"59条・則附則。事後請求ができるのは支給決定通知の翌日から1年以内。",topic:"前払一時金"},
{id:"X2-118",s:2,q:"障害(補償)等年金前払一時金は、同一の事由について何回でも請求することができる。",a:false,e:"59条・則附則。前払一時金の請求は同一の事由について1回に限られる。",topic:"前払一時金"},
{id:"X2-119",s:2,q:"障害(補償)等給付は、業務上の傷病が治った後に身体に障害が存する場合に支給される。",a:true,e:"15条。傷病が治ゆ(症状固定)した後に障害等級に該当する障害が残った場合に支給される。",topic:"障害(補償)等給付"},
{id:"X2-120",s:2,q:"障害(補償)等給付を受ける権利は、傷病が治った日の翌日から起算して5年を経過したときは時効によって消滅する。",a:true,e:"42条。障害(補償)等給付・遺族(補償)等給付は5年。障害は治ゆ日の翌日から起算する。",topic:"時効"},
{id:"X2-121",s:2,q:"両眼が失明したものは、障害等級第1級に該当する。",a:true,e:"則別表第1。両眼が失明したものは障害等級第1級(1号)。",topic:"障害(補償)等給付"},
{id:"X2-122",s:2,q:"遺族(補償)等年金を受けることができる遺族は、労働者の配偶者、子、父母、孫、祖父母及び兄弟姉妹であって、労働者の死亡当時その収入によって生計を維持していたものである。",a:true,e:"16条の2第1項。配偶者は事実婚を含む。妻以外は年齢又は障害の要件も必要。",topic:"遺族(補償)等年金"},
{id:"X2-123",s:2,q:"労働者の死亡当時胎児であった子が出生したときは、将来に向かって、その子は労働者の死亡当時その収入によって生計を維持していた子とみなされる。",a:true,e:"16条の2第2項。胎児は出生の時から将来に向かって受給資格者となる。",topic:"遺族(補償)等年金"},
{id:"X2-124",s:2,q:"遺族(補償)等年金の若年支給停止を受けている受給権者であっても、遺族(補償)等年金前払一時金を請求することができる。",a:true,e:"附則43条・60条。55歳以上60歳未満で60歳まで支給停止中の者も、前払一時金は請求できる。",topic:"前払一時金"},
{id:"X2-125",s:2,q:"兄弟姉妹は、18歳に達する日以後の最初の3月31日までの間にあるか、55歳以上であるか、又は一定の障害の状態にあれば、遺族(補償)等年金の受給資格者となりうる。",a:true,e:"16条の2第1項4号・附則43条。55歳以上60歳未満の兄弟姉妹は若年停止の対象となり、順位も後順位。",topic:"遺族(補償)等年金"},
{id:"X2-126",s:2,q:"祖父母が遺族(補償)等年金の受給資格者となるには、労働者の死亡当時60歳以上であることを要し、55歳以上60歳未満の祖父母は受給資格者とならない。",a:false,e:"16条の2・附則43条。夫・父母・祖父母は55歳以上で受給資格者となり、60歳未満の間は支給停止(若年停止)となる。",topic:"遺族(補償)等年金"},
{id:"X2-127",s:2,q:"遺族(補償)等年金の受給資格者の障害要件は、障害等級第5級以上に該当する障害の状態、又は傷病が治らないで労働が高度の制限を受けるか高度の制限を加えることを要する状態にあることである。",a:true,e:"16条の2第1項・則15条。障害要件は5級以上又はこれと同程度の状態。",topic:"遺族(補償)等年金"},
{id:"X2-128",s:2,q:"子が遺族(補償)等年金の受給資格者となるための年齢要件は、労働者の死亡当時20歳未満であることである。",a:false,e:"16条の2第1項2号。子・孫は18歳に達する日以後の最初の3月31日までの間にあること(又は一定の障害)。",topic:"遺族(補償)等年金"},
{id:"X2-129",s:2,q:"遺族が1人の場合の遺族(補償)等年金の額は、原則として給付基礎日額の153日分である。",a:true,e:"16条の3・別表第1。1人153日分(55歳以上又は一定障害の妻は175日分)、2人201、3人223、4人以上245日分。",topic:"遺族(補償)等年金"},
{id:"X2-130",s:2,q:"遺族が1人で、その遺族が55歳以上の妻である場合の遺族(補償)等年金の額は、給付基礎日額の201日分である。",a:false,e:"別表第1。55歳以上又は一定障害の妻1人の場合は175日分。201日分は遺族2人の額。",topic:"遺族(補償)等年金"},
{id:"X2-131",s:2,q:"遺族(補償)等年金の額の算定の基礎となる遺族の数には、受給権者と生計を同じくしているか否かを問わず、すべての受給資格者が含まれる。",a:false,e:"16条の3第1項。受給権者と生計を同じくしている受給資格者に限り算入する。",topic:"遺族(補償)等年金"},
{id:"X2-132",s:2,q:"遺族が4人以上の場合の遺族(補償)等年金の額は、給付基礎日額の245日分である。",a:true,e:"別表第1。4人以上は245日分が上限。",topic:"遺族(補償)等年金"},
{id:"X2-133",s:2,q:"遺族(補償)等年金を受ける権利を有する者が2人以上あるときは、年金額をその人数で除して得た額がそれぞれに支給される。",a:true,e:"16条の3第2項。受給権者が2人以上ある場合は等分して支給される。",topic:"遺族(補償)等年金"},
{id:"X2-134",s:2,q:"遺族(補償)等年金の受給権者が、直系血族又は直系姻族以外の者の養子となったときは、その受給権は消滅する。",a:true,e:"16条の4第1項3号。届出をしていないが事実上養子縁組関係と同様の事情にある場合を含む。",topic:"遺族(補償)等年金の失権"},
{id:"X2-135",s:2,q:"遺族(補償)等年金の受給権者である妻が、亡夫の父母(直系姻族)の養子となったときも、その受給権は消滅する。",a:false,e:"16条の4第1項3号。直系血族又は直系姻族の養子となった場合は失権しない。",topic:"遺族(補償)等年金の失権"},
{id:"X2-136",s:2,q:"遺族(補償)等年金の受給権者が離縁によって死亡した労働者との親族関係が終了したときは、その受給権は消滅する。",a:true,e:"16条の4第1項4号。離縁による親族関係の終了は失権事由。",topic:"遺族(補償)等年金の失権"},
{id:"X2-137",s:2,q:"障害を理由として受給資格者とされていた子が、18歳に達する日以後の最初の3月31日を過ぎた後にその障害の状態でなくなったときは、受給権は消滅する。",a:true,e:"16条の4第1項6号。障害要件で受給していた者がその事情に該当しなくなれば失権する(年齢要件を満たす間を除く)。",topic:"遺族(補償)等年金の失権"},
{id:"X2-138",s:2,q:"遺族(補償)等年金の受給権者の所在が6か月以上明らかでない場合には、同順位者又は次順位者の申請によって、所在不明の間その支給が停止される。",a:false,e:"16条の5第1項。所在不明による支給停止は1年以上明らかでない場合。",topic:"遺族(補償)等年金"},
{id:"X2-139",s:2,q:"所在不明により支給停止を受けた遺族(補償)等年金の受給権者は、いつでも、その支給停止の解除を申請することができる。",a:true,e:"16条の5第2項。所在が明らかになった受給権者は、いつでも支給停止の解除を申請できる。",topic:"遺族(補償)等年金"},
{id:"X2-140",s:2,q:"労働者の死亡前に、その死亡によって遺族(補償)等年金を受けることができる先順位又は同順位となるべき者を故意に死亡させた者は、遺族(補償)等年金を受けることができる遺族としない。",a:true,e:"16条の9第2項。労働者を故意に死亡させた者も遺族(補償)等給付を受けることができる遺族としない(同条1項)。",topic:"遺族(補償)等給付"},
{id:"X2-141",s:2,q:"遺族(補償)等一時金を受けることができる遺族の第1順位は、労働者の死亡当時その収入によって生計を維持していた子である。",a:false,e:"16条の7第1項。第1順位は配偶者。次いで生計維持の子・父母・孫・祖父母、生計維持でない子・父母・孫・祖父母、兄弟姉妹。",topic:"遺族(補償)等一時金"},
{id:"X2-142",s:2,q:"遺族(補償)等一時金を受けることができる遺族のうち、兄弟姉妹は、労働者の死亡当時生計を維持されていたか否かにかかわらず最後順位である。",a:true,e:"16条の7。兄弟姉妹は生計維持の有無を問わず最後順位。",topic:"遺族(補償)等一時金"},
{id:"X2-143",s:2,q:"遺族(補償)等年金の受給権者が全員失権し他に受給資格者がない場合で、既に支給された年金と前払一時金の合計額が給付基礎日額の1,000日分に満たないときは、その差額が遺族(補償)等一時金として支給される。",a:true,e:"16条の6第1項2号。失権時に受給資格者がなく、支給済額が1,000日分未満なら差額を一時金で支給。",topic:"遺族(補償)等一時金"},
{id:"X2-144",s:2,q:"遺族(補償)等一時金を受けることができる同順位の遺族が2人以上ある場合には、その額は人数で等分される。",a:true,e:"16条の3第2項の準用。同順位者が2人以上あれば等分する。",topic:"遺族(補償)等一時金"},
{id:"X2-145",s:2,q:"遺族(補償)等年金前払一時金の最高額は、給付基礎日額の1,340日分である。",a:false,e:"60条・附則。遺族は200〜1,000日分の5段階。1,340日分は障害1級の前払一時金の最高額。",topic:"前払一時金"},
{id:"X2-146",s:2,q:"遺族特別支給金は、受給権者が2人以上あるときは、それぞれに300万円ずつ支給される。",a:false,e:"特別支給金支給規則5条。遺族特別支給金300万円を受給権者の人数で等分する。",topic:"特別支給金"},
{id:"X2-147",s:2,q:"遺族(補償)等年金の受給資格者のうち、55歳以上60歳未満の夫・父母・祖父母・兄弟姉妹は、一定の障害の状態にない限り、他の受給資格者より後順位となる。",a:true,e:"附則43条。順位は配偶者→子→父母→孫→祖父母→兄弟姉妹の後に、55〜60歳未満の夫→父母→祖父母→兄弟姉妹。",topic:"遺族(補償)等年金"},
{id:"X2-148",s:2,q:"葬祭料(葬祭給付)は、葬祭を行う者に支給されるため、遺族がなく事業主が社葬として葬祭を行った場合には事業主に支給されうる。",a:true,e:"17条・通達。葬祭料は通常は遺族に支給されるが、遺族がなく社葬とした場合等は葬祭を行った者(事業主)に支給。",topic:"葬祭料"},
{id:"X2-149",s:2,q:"葬祭料(葬祭給付)を受ける権利の時効は、労働者が死亡した日の翌日から起算して5年である。",a:false,e:"42条。葬祭料(葬祭給付)は2年。5年は障害(補償)等給付・遺族(補償)等給付。",topic:"時効"},
{id:"X2-150",s:2,q:"介護(補償)等給付は、障害(補償)等年金又は傷病(補償)等年金の受給権者で所定の障害により常時又は随時介護を要する状態にあり、かつ常時又は随時介護を受けているときに、その介護を受けている間支給される。",a:true,e:"12条の8第4項・19条の2。年金受給権者であることが要件で、介護を受けている間に月単位で支給。",topic:"介護(補償)等給付"},
{id:"X2-151",s:2,q:"障害(補償)等一時金を受けた者であっても、常時介護を受けている場合には、介護(補償)等給付が支給される。",a:false,e:"12条の8第4項。介護(補償)等給付は障害(補償)等年金又は傷病(補償)等年金の受給権者が対象。一時金受給者は対象外。",topic:"介護(補償)等給付"},
{id:"X2-152",s:2,q:"介護(補償)等給付は、病院又は診療所に入院している間は支給されない。",a:true,e:"12条の8第4項。入院中は病院等で介護に相当するサービスを受けるため支給しない。",topic:"介護(補償)等給付"},
{id:"X2-153",s:2,q:"介護(補償)等給付は、障害者総合支援法に規定する障害者支援施設に入所して生活介護を受けている間も支給される。",a:false,e:"12条の8第4項1号。障害者支援施設に入所し生活介護を受けている間、特別養護老人ホーム等に入所している間は支給しない。",topic:"介護(補償)等給付"},
{id:"X2-154",s:2,q:"障害等級第2級の障害(補償)等年金の受給権者であれば、障害の部位を問わず、介護を要する状態にある限り介護(補償)等給付の対象となる。",a:false,e:"施行規則(別表第3)。2級は精神神経・胸腹部臓器の障害に限られる。",topic:"介護(補償)等給付"},
{id:"X2-155",s:2,q:"介護(補償)等給付は月を単位として支給され、親族等の介護を受けていて介護費用を支出していない月でも、最低保障額に相当する額が支給されうる。",a:true,e:"19条の2・施行規則。親族等による介護で費用支出がない月も、介護を受け始めた月を除き最低保障額を支給。",topic:"介護(補償)等給付"},
{id:"X2-156",s:2,q:"介護を受け始めた月において介護費用を支出していない場合でも、その月について最低保障額が支給される。",a:false,e:"施行規則。介護を受け始めた月は、介護費用を支出した場合にその額(上限あり)が支給され、最低保障額の適用はない。",topic:"介護(補償)等給付"},
{id:"X2-157",s:2,q:"傷病(補償)等年金の受給権者が介護(補償)等給付を請求する場合は、傷病(補償)等年金の支給決定を受けた後に行う。",a:true,e:"施行規則。障害(補償)等年金の受給権者は年金の請求と同時又は請求後、傷病年金受給者は支給決定後に請求する。",topic:"介護(補償)等給付"},
{id:"X2-158",s:2,q:"介護(補償)等給付を受ける権利は、介護を受けた月の翌月の初日から起算して2年を経過したときは時効によって消滅する。",a:true,e:"42条・通達。介護(補償)等給付は2年で、介護を受けた月の翌月の初日から起算。",topic:"時効"},
{id:"X2-159",s:2,q:"二次健康診断等給付は、一次健康診断の結果その他の事情により既に脳血管疾患又は心臓疾患の症状を有すると認められる労働者については行われない。",a:true,e:"26条1項かっこ書。既に脳・心臓疾患の症状を有する者は、療養の対象となるため二次健康診断等給付の対象外。",topic:"二次健康診断等給付"},
{id:"X2-160",s:2,q:"二次健康診断等給付の請求は、原則として一次健康診断を受けた日から3か月以内に行わなければならない。",a:true,e:"施行規則。天災その他やむを得ない理由がある場合を除き、一次健康診断の受診日から3か月以内。",topic:"二次健康診断等給付"},
{id:"X2-161",s:2,q:"二次健康診断は、1年度につき2回まで受けることができる。",a:false,e:"26条2項。二次健康診断は1年度につき1回に限る。特定保健指導は二次健康診断ごとに1回。",topic:"二次健康診断等給付"},
{id:"X2-162",s:2,q:"特定保健指導は医師のみが行うものとされ、保健師が行うことはできない。",a:false,e:"26条2項2号。特定保健指導は医師又は保健師による面接で行われる。",topic:"二次健康診断等給付"},
{id:"X2-163",s:2,q:"二次健康診断等給付は、業務災害に関する保険給付の一つとして位置付けられている。",a:false,e:"7条1項4号。二次健康診断等給付は業務災害・複数業務要因災害・通勤災害とは別の独立した保険給付。",topic:"二次健康診断等給付"},
{id:"X2-164",s:2,q:"二次健康診断を受けた労働者から一定期間内にその結果を証明する書面の提出を受けた事業者は、その結果に基づき医師から意見を聴かなければならない。",a:true,e:"27条。安衛法66条の4の規定の適用により、事業者は提出された二次健康診断の結果について医師の意見を聴く。",topic:"二次健康診断等給付"},
{id:"X2-165",s:2,q:"年金たる保険給付の支給は、支給すべき事由が生じた月から始め、その権利が消滅した月で終わる。",a:false,e:"9条1項。支給すべき事由が生じた月の翌月から始め、権利が消滅した月で終わる。",topic:"年金の支給期間"},
{id:"X2-166",s:2,q:"年金たる保険給付は、その支給を停止すべき事由が生じたときは、その事由が生じた月の翌月からその事由が消滅した月までの間は支給されない。",a:true,e:"9条2項。支給停止は事由が生じた月の翌月から事由が消滅した月まで。",topic:"年金の支給期間"},
{id:"X2-167",s:2,q:"年金たる保険給付は、毎年2月、5月、8月及び11月の4期に、それぞれその前月分までが支払われる。",a:false,e:"9条3項。2月・4月・6月・8月・10月・12月の6期に前月分までを支払う。",topic:"年金の支給期間"},
{id:"X2-168",s:2,q:"保険給付を受ける権利を有する者が死亡した場合、その者に支給すべき未支給の保険給付は、その者の死亡当時生計を同じくしていた配偶者、子、父母、孫、祖父母又は兄弟姉妹が請求することができる。",a:true,e:"11条1項。未支給の保険給付の請求権者は生計同一の配偶者等(遺族(補償)等年金は次順位の遺族)。",topic:"未支給の保険給付"},
{id:"X2-169",s:2,q:"未支給の遺族(補償)等年金は、死亡した受給権者と生計を同じくしていた者であれば、次順位の遺族以外の者も請求することができる。",a:false,e:"11条1項かっこ書。遺族(補償)等年金の未支給分は、当該年金を受けることができる他の遺族(次順位者等)が請求する。",topic:"未支給の保険給付"},
{id:"X2-170",s:2,q:"未支給の保険給付を受けるべき同順位者が2人以上あるときは、その1人がした請求は全員のためその全額につきしたものとみなされる。",a:true,e:"11条4項。1人がした請求は全員のため、1人に対する支給は全員に対してしたものとみなす。",topic:"未支給の保険給付"},
{id:"X2-171",s:2,q:"年金たる保険給付を減額して改定すべき事由が生じたにもかかわらず、その翌月以後の分として減額しない額の年金が支払われたときは、その差額は以後の年金の内払とみなすことができる。",a:true,e:"12条1項。減額改定分の過払いは、その後に支払うべき年金の内払とみなすことができる。",topic:"内払・充当"},
{id:"X2-172",s:2,q:"同一の傷病について休業(補償)等給付を受けていた者が傷病(補償)等年金を受けることとなった後も休業(補償)等給付が支払われたときは、その休業(補償)等給付は傷病(補償)等年金の内払とみなされる。",a:true,e:"12条2項。同一傷病で給付が切り替わった後に支払われた従前の給付は、新たな年金の内払とみなす。",topic:"内払・充当"},
{id:"X2-173",s:2,q:"年金の受給権者の死亡後にその年金の過誤払が行われた場合、その返還金債権に係る債務の弁済をすべき者に支払うべき遺族(補償)等年金等があるときは、その支払金をその債権に充当することができる。",a:true,e:"12条の2。受給権者死亡後の過誤払は、返還義務者に支払う遺族(補償)等年金等に充当できる。",topic:"内払・充当"},
{id:"X2-174",s:2,q:"租税その他の公課は、保険給付として支給を受けた金銭を標準として課することができない。",a:true,e:"12条の6。保険給付には所得税等の公課を課さない(公課の禁止)。",topic:"受給権の保護"},
{id:"X2-175",s:2,q:"同一の事由により障害厚生年金及び障害基礎年金が支給される場合、障害(補償)等年金は、調整率0.73を乗じて減額される。",a:true,e:"別表第1。障害は厚年+基礎0.73、厚年のみ0.83、基礎のみ0.88。",topic:"社会保険との併給調整"},
{id:"X2-176",s:2,q:"同一の事由により障害厚生年金のみが支給される場合、障害(補償)等年金の調整率は0.73である。",a:false,e:"別表第1。障害厚生年金のみの場合は0.83。0.73は障害厚生年金と障害基礎年金の両方が支給される場合。",topic:"社会保険との併給調整"},
{id:"X2-177",s:2,q:"同一の事由により障害基礎年金のみが支給される場合、障害(補償)等年金の調整率は0.88である。",a:true,e:"別表第1。障害基礎年金のみは0.88。",topic:"社会保険との併給調整"},
{id:"X2-178",s:2,q:"同一の事由により遺族厚生年金及び遺族基礎年金が支給される場合、遺族(補償)等年金に乗じる調整率は0.73である。",a:false,e:"別表第1。遺族は厚年+基礎0.80、厚年のみ0.84、基礎のみ0.88。0.73は障害の場合。",topic:"社会保険との併給調整"},
{id:"X2-179",s:2,q:"労災保険の年金と厚生年金保険の年金が同一の事由で支給される場合、厚生年金保険の年金の側が減額される。",a:false,e:"別表第1。社会保険の年金は全額支給され、労災保険の年金の側が調整率により減額される。",topic:"社会保険との併給調整"},
{id:"X2-180",s:2,q:"社会保険の年金との併給調整により減額されるのは保険給付であり、障害特別年金などの特別支給金は併給調整による減額の対象とならない。",a:true,e:"通達。特別支給金は保険給付ではないため併給調整されない。",topic:"社会保険との併給調整"},
{id:"X2-181",s:2,q:"労働者が重大な過失により事故を生じさせた場合の支給制限は、休業(補償)等給付や障害(補償)等給付等について、その額の100分の50を減ずることにより行われる。",a:false,e:"12条の2の2第2項・通達。重大過失による支給制限は100分の30の減額。",topic:"支給制限"},
{id:"X2-182",s:2,q:"労働者が正当な理由なく療養に関する指示に従わないことにより傷病の回復を妨げたときは、政府は保険給付の全部又は一部を行わないことができる。",a:true,e:"12条の2の2第2項。療養の指示違反で程度を増進させ又は回復を妨げたときは全部又は一部を行わないことができる。",topic:"支給制限"},
{id:"X2-183",s:2,q:"重大な過失による支給制限の対象には療養(補償)等給付も含まれ、療養の給付の額の100分の30が減じられる。",a:false,e:"12条の2の2第2項・通達。支給制限の対象は休業・傷病・障害等で、療養(補償)等給付は制限の対象とされない。",topic:"支給制限"},
{id:"X2-184",s:2,q:"偽りその他不正の手段により保険給付を受けた者があるときは、政府は、その保険給付に要した費用に相当する金額の全部又は一部をその者から徴収することができる。",a:true,e:"12条の3第1項。不正受給者からの費用徴収。",topic:"費用徴収"},
{id:"X2-185",s:2,q:"不正受給が事業主の虚偽の報告又は証明によるものであるときは、政府は、その事業主に対し、不正受給者と連帯して徴収金を納付すべきことを命ずることができる。",a:true,e:"12条の3第2項。事業主が虚偽の報告・証明をした場合は連帯納付を命じうる(医師の虚偽診断書も同様)。",topic:"費用徴収"},
{id:"X2-186",s:2,q:"事業主が重大な過失により保険関係成立届を提出していない期間中に生じた事故について保険給付を行った場合、政府は保険給付額の全額を事業主から徴収する。",a:false,e:"31条1項1号・通達。全額(100%)は故意の場合。重大な過失は40%。",topic:"費用徴収"},
{id:"X2-187",s:2,q:"事業主が一般保険料を納付しない期間(督促状の指定期限後)中に生じた事故について保険給付を行った場合、費用徴収の額は、保険給付の額に滞納率(最高100分の40)を乗じて得た額となる。",a:true,e:"31条1項2号・通達。滞納期間中の事故は滞納率(上限40%)を乗じた額を徴収。",topic:"費用徴収"},
{id:"X2-188",s:2,q:"事業主が故意又は重大な過失により生じさせた業務災害の原因である事故について保険給付を行った場合、政府は保険給付の額の100分の40に相当する額を事業主から徴収する。",a:false,e:"31条1項3号・通達。事業主の故意・重過失による業務災害の費用徴収は30%。",topic:"費用徴収"},
{id:"X2-189",s:2,q:"事業主からの費用徴収(31条1項)の対象となる保険給付には、療養(補償)等給付も含まれる。",a:false,e:"31条1項・通達。費用徴収の対象から療養(補償)等給付・介護(補償)等給付等は除かれる。",topic:"費用徴収"},
{id:"X2-190",s:2,q:"政府は、保険給付を受ける者が正当な理由なく行政庁の報告命令や医師の診断を受けるべき命令に従わないときは、保険給付の支払を一時差し止めることができる。",a:true,e:"47条の3。報告・出頭・受診命令等に従わない場合の保険給付の一時差止め。",topic:"支給制限"},
{id:"X2-191",s:2,q:"事業主が労働者に民事損害賠償を行う場合、障害(補償)等年金等の受給権者については、前払一時金の最高限度額に相当する額の限度で、その損害賠償の履行を猶予することができる。",a:true,e:"附則64条1項。年金給付との調整のため、前払一時金最高限度額相当額の限度で履行猶予ができる。",topic:"損害賠償との調整"},
{id:"X2-192",s:2,q:"特別支給金は保険給付ではないため、事業主が支払う損害賠償額から特別支給金相当額を控除することはできない。",a:true,e:"コック食品事件(最判平8.2.23)。特別支給金は損害の填補の性質を有しないため損害額から控除されない。",topic:"損害賠償との調整"},
{id:"X2-193",s:2,q:"特別支給金は保険給付と同様に、事業主の故意・重大な過失による災害の場合の費用徴収の対象となる。",a:false,e:"31条1項。費用徴収の対象は保険給付であり、社会復帰促進等事業としての特別支給金は対象外。",topic:"費用徴収"},
{id:"X2-194",s:2,q:"社会復帰促進等事業は、社会復帰促進事業、被災労働者等援護事業及び安全衛生確保等事業の3つからなる。",a:true,e:"29条1項1号〜3号。",topic:"社会復帰促進等事業"},
{id:"X2-195",s:2,q:"賃金の支払の確保を図るために必要な事業は、社会復帰促進等事業に含まれる。",a:true,e:"29条1項3号。安全衛生確保等事業に賃金の支払の確保を図るための事業が含まれる(未払賃金立替払事業)。",topic:"社会復帰促進等事業"},
{id:"X2-196",s:2,q:"被災労働者の子の学資等を援護するための労災就学等援護費は、保険給付として支給される。",a:false,e:"29条1項2号。労災就学等援護費は被災労働者等援護事業として行われ、保険給付ではない。",topic:"社会復帰促進等事業"},
{id:"X2-197",s:2,q:"障害特別支給金の支給の申請は、傷病が治った日の翌日から起算して3年以内に行わなければならない。",a:false,e:"特別支給金支給規則4条。障害特別支給金の申請期限は5年。",topic:"特別支給金"},
{id:"X2-198",s:2,q:"遺族特別支給金の支給の申請は、労働者の死亡の日の翌日から起算して2年以内に行わなければならない。",a:false,e:"特別支給金支給規則5条。遺族特別支給金の申請期限は5年。2年は休業特別支給金。",topic:"特別支給金"},
{id:"X2-199",s:2,q:"障害特別年金などボーナス特別支給金の算定基礎日額は、算定基礎年額を12で除して得た額である。",a:false,e:"特別支給金支給規則6条。算定基礎日額は算定基礎年額を365で除して得た額。",topic:"特別支給金"},
{id:"X2-200",s:2,q:"障害特別年金の額は、障害等級第1級の場合、算定基礎日額の313日分である。",a:true,e:"特別支給金支給規則7条・別表第2。日数は障害(補償)等年金と同じ(1級313日分〜7級131日分)。",topic:"特別支給金"},
{id:"X2-201",s:2,q:"遺族特別年金の額は、遺族(補償)等年金と同様に遺族の人数に応じて定められ、算定基礎日額の153日分から245日分である。",a:true,e:"特別支給金支給規則9条・別表第2。遺族の人数区分・日数は遺族(補償)等年金と同じ。",topic:"特別支給金"},
{id:"X2-202",s:2,q:"傷病特別年金は、傷病(補償)等年金の受給権者に支給される。",a:true,e:"特別支給金支給規則11条。傷病等級に応じ算定基礎日額の313・277・245日分。",topic:"特別支給金"},
{id:"X2-203",s:2,q:"保険給付に関する決定に不服のある者は、処分があった日の翌日から起算して60日以内に、労働者災害補償保険審査官に審査請求をしなければならない。",a:false,e:"38条1項・労働保険審査官及び労働保険審査会法8条。処分があったことを知った日の翌日から3か月以内。",topic:"不服申立て"},
{id:"X2-204",s:2,q:"審査官の決定に不服のある者は、決定書の謄本が送付された日の翌日から起算して3か月以内に、労働保険審査会に再審査請求をすることができる。",a:false,e:"労働保険審査官及び労働保険審査会法38条。再審査請求期間は2か月。3か月は審査請求期間。",topic:"不服申立て"},
{id:"X2-205",s:2,q:"審査請求をした日から3か月を経過しても審査請求についての決定がないときは、審査請求人は、審査官が審査請求を棄却したものとみなすことができる。",a:true,e:"38条2項。決定がないまま3か月を経過すれば棄却とみなして、再審査請求や取消訴訟に進める。",topic:"不服申立て"},
{id:"X2-206",s:2,q:"保険給付に関する処分の取消しの訴えは、再審査請求に対する労働保険審査会の裁決を経た後でなければ提起することができない。",a:false,e:"40条。審査請求に対する審査官の決定を経れば取消訴訟を提起できる(再審査請求前置は平成28年に廃止)。",topic:"不服申立て"},
{id:"X2-207",s:2,q:"審査請求及び再審査請求は、時効の完成猶予及び更新に関しては、裁判上の請求とみなされる。",a:true,e:"38条3項。",topic:"不服申立て"},
{id:"X2-208",s:2,q:"保険給付に関する処分の取消しの訴えは、審査請求をすることなく、直ちに提起することができる。",a:false,e:"40条。審査請求前置が維持されており、審査請求に対する決定を経た後でなければ提起できない(3か月経過等の例外あり)。",topic:"不服申立て"},
{id:"X2-209",s:2,q:"労働者災害補償保険審査官は、厚生労働省本省にのみ置かれる。",a:false,e:"労働保険審査官及び労働保険審査会法2条。審査官は各都道府県労働局に置かれる。",topic:"不服申立て"},
{id:"X2-210",s:2,q:"休業(補償)等給付を受ける権利の時効は、療養のため労働することができず賃金を受けない日ごとに、その翌日から起算する。",a:true,e:"42条・通達。休業(補償)等給付は2年で、休業日ごとにその翌日から起算する。",topic:"時効"},
{id:"X2-211",s:2,q:"障害(補償)等年金差額一時金を受ける権利は、2年を経過したときは時効によって消滅する。",a:false,e:"42条・58条。障害(補償)等年金差額一時金は障害(補償)等給付に属し、時効は5年。",topic:"時効"},
{id:"X2-212",s:2,q:"保険給付を受けるべき者が事故のため自ら請求等の手続を行うことが困難である場合には、事業主は、その手続を行うことができるように助力しなければならない。",a:true,e:"則23条1項。事業主の助力義務。",topic:"請求手続"},
{id:"X2-213",s:2,q:"保険給付を受けるべき者から保険給付を受けるために必要な証明を求められたときは、事業主は速やかに証明をしなければならない。",a:true,e:"則23条2項。事業主の証明義務。",topic:"請求手続"},
{id:"X2-214",s:2,q:"事業主が証明を拒んだ場合には、労働者は保険給付の請求をすることができない。",a:false,e:"則23条・通達。事業主の証明が得られない場合でも、その事情を記載するなどして請求することができる。",topic:"請求手続"},
{id:"X2-215",s:2,q:"事業主は、当該事業主の事業に係る保険給付の請求について、所轄労働基準監督署長に意見を申し出ることができる。",a:true,e:"則23条の2。事業主の意見申出制度。",topic:"請求手続"},
{id:"X2-216",s:2,q:"複数業務要因災害とは、複数事業労働者の2以上の事業の業務を要因とする負傷、疾病、障害又は死亡をいう。",a:true,e:"7条1項2号。",topic:"複数業務要因災害"},
{id:"X2-217",s:2,q:"複数業務要因災害の対象となる疾病には、脳・心臓疾患や精神障害などが含まれる。",a:true,e:"施行規則。労基則別表第1の2第8号(脳・心臓疾患)・第9号(精神障害)その他2以上の事業の業務を要因とすることが明らかな疾病。",topic:"複数業務要因災害"},
{id:"X2-218",s:2,q:"複数業務要因災害に関する保険給付の名称には、業務災害と同様に「補償」の文字が付く。",a:false,e:"20条の2以下。複数事業労働者療養給付・休業給付等と呼び、補償の文字は付かない。",topic:"複数業務要因災害"},
{id:"X2-219",s:2,q:"複数事業労働者とは、事業主が同一人でない2以上の事業に使用される労働者をいう。",a:true,e:"1条。",topic:"複数業務要因災害"},
{id:"X2-220",s:2,q:"同一の事業主が経営する2つの事業場で就労している労働者も、複数事業労働者に該当する。",a:false,e:"1条。複数事業労働者は事業主が同一人でない2以上の事業に使用される者に限られる。",topic:"複数業務要因災害"},
{id:"X2-221",s:2,q:"特別加入者であっても、複数事業労働者に該当する場合がある。",a:true,e:"通達。労働者として雇用されつつ特別加入している場合や、複数の特別加入をしている場合も複数事業労働者となりうる。",topic:"複数業務要因災害"},
{id:"X2-222",s:2,q:"国庫は、労働者災害補償保険事業に要する費用の3分の1を負担しなければならない。",a:false,e:"32条。国庫は予算の範囲内で費用の一部を補助することができる(任意の補助で定率負担ではない)。",topic:"費用の負担"},
{id:"X2-223",s:2,q:"政府は、保険給付に関して必要があると認めるときは、保険給付を受け又は受けようとする者に対し、その指定する医師の診断を受けるべきことを命ずることができる。",a:true,e:"47条の2。受診命令。従わないときは47条の3により支払の一時差止めがありうる。",topic:"雑則"},
{id:"X2-224",s:2,q:"業務災害に関する保険給付は、労働基準法に規定する災害補償の事由が生じた場合に行われる。",a:true,e:"12条の8第2項。療養・休業・障害・遺族・葬祭の補償事由が生じた場合に行う(傷病・介護は別途の要件)。",topic:"労基法との関係"},
{id:"X2-225",s:2,q:"通勤災害に関する保険給付には、傷病年金及び介護給付は含まれない。",a:false,e:"21条。通勤災害にも療養・休業・障害・遺族・葬祭給付、傷病年金、介護給付の7種類がある。",topic:"保険給付の種類"},
{id:"X2-226",s:2,q:"通勤災害に係る傷病年金の額は、業務災害の傷病補償年金の額より一定割合低く定められている。",a:false,e:"23条2項による18条の準用。通勤災害の給付額は業務災害と同額(一部負担金を除き差異はない)。",topic:"保険給付の種類"},
{id:"X2-227",s:2,q:"船舶が沈没した際に現にその船舶に乗っていた労働者の生死が3か月間わからない場合には、遺族(補償)等給付等の支給に関しては、その船舶が沈没した日に死亡したものと推定する。",a:true,e:"10条。船舶・航空機事故の生死不明3か月で事故日に死亡と推定する。",topic:"死亡の推定"},
{id:"X2-228",s:2,q:"航空機の墜落事故による行方不明者について、労災保険法上の死亡の推定が働くのは、生死不明の期間が1年に達した場合である。",a:false,e:"10条。労災保険法の死亡の推定は3か月。1年は民法の危難失踪の期間。",topic:"死亡の推定"},
{id:"X2-229",s:2,q:"学生アルバイトであっても、労働基準法上の労働者に該当する限り、労災保険の適用を受ける。",a:true,e:"労働者は労基法9条と同義で、雇用形態や学生か否かを問わず使用され賃金を支払われる者は対象。",topic:"適用・労働者性"},
{id:"X2-230",s:2,q:"暫定任意適用事業で労災保険に加入していない事業に使用される労働者は、業務災害を被っても労災保険の保険給付を受けることはできない。",a:true,e:"整備法5条。任意加入の申請・認可がなく保険関係が成立していないため、保険給付の対象とならない。",topic:"暫定任意適用事業"},
{id:"X2-231",s:2,q:"休業(補償)等給付の額は、療養のため労働できない日について、1日につき休業給付基礎日額の100分の80に相当する額である。",a:false,e:"14条1項。休業(補償)等給付は100分の60。休業特別支給金20%と合わせて80%となる。",topic:"休業(補償)等給付"},
{id:"X2-232",s:2,q:"障害(補償)等給付は、障害の程度に応じて障害等級第1級から第14級に区分され、同一の事由で年金と一時金の両方が支給されることはない。",a:true,e:"15条。1〜7級は年金、8〜14級は一時金で、いずれか一方が支給される。",topic:"障害(補償)等給付"},
{id:"X2-233",s:2,q:"1眼が失明したものは、障害等級第7級に該当し、障害(補償)等年金の対象となる。",a:false,e:"則別表第1。1眼が失明し又は1眼の視力が0.02以下になったものは第8級で、一時金の対象。",topic:"障害(補償)等給付"},
{id:"X2-234",s:2,q:"遺族(補償)等年金の受給権者が婚姻した場合でも、その婚姻が届出をしていない事実上の婚姻であるときは受給権は消滅しない。",a:false,e:"16条の4第1項2号。婚姻には届出をしていないが事実上婚姻関係と同様の事情にある場合を含み、失権する。",topic:"遺族(補償)等年金の失権"},
{id:"X2-235",s:2,q:"遺族(補償)等年金の受給権者が死亡したときは、その受給権は消滅し、同順位者がなく後順位者があるときは次順位者に受給権が移る。",a:true,e:"16条の4。遺族(補償)等年金には転給制度がある。",topic:"遺族(補償)等年金"},
{id:"X2-236",s:2,q:"遺族(補償)等年金の受給権者が2人以上あるときは、原則としてそのうち1人を年金の請求及び受領についての代表者に選任しなければならない。",a:true,e:"施行規則。世帯を異にする等やむを得ない事情がある場合を除き代表者を選任する。",topic:"遺族(補償)等年金"},
{id:"X2-237",s:2,q:"労働者の死亡当時その収入によって生計を維持していたとは、もっぱら又は主として労働者の収入によって生計を維持していたことを要し、共働きの妻は含まれない。",a:false,e:"16条の2・通達。一部でも労働者の収入で生計を維持していれば足り、共働きの場合も該当する。",topic:"遺族(補償)等年金"},
{id:"X2-238",s:2,q:"介護(補償)等給付の対象となるのは、障害(補償)等年金又は傷病(補償)等年金の受給権者であり、通勤災害による障害年金・傷病年金の受給権者は対象とならない。",a:false,e:"24条。通勤災害にも介護給付があり、障害年金・傷病年金の受給権者は要件を満たせば対象となる。",topic:"介護(補償)等給付"},
{id:"X2-239",s:2,q:"二次健康診断等給付を受ける権利の時効は5年である。",a:false,e:"42条。二次健康診断等給付は2年。起算は一次健診結果を了知しうる日の翌日。",topic:"時効"},
{id:"X2-240",s:2,q:"遺族(補償)等給付を受ける権利は、労働者が死亡した日の翌日から起算して5年を経過したときは時効によって消滅する。",a:true,e:"42条。遺族(補償)等給付は5年、死亡日の翌日から起算。",topic:"時効"},
{id:"X2-241",s:2,q:"傷病(補償)等年金の受給権者の傷病が治ったときは、傷病(補償)等年金は終了し、障害が残れば障害(補償)等給付の対象となる。",a:true,e:"18条・15条。治ゆにより傷病年金の受給権は消滅し、障害等級に該当すれば障害(補償)等給付が支給される。",topic:"傷病(補償)等年金"},
{id:"X2-242",s:2,q:"障害等級第13級以上に該当する身体障害が2以上ある場合には、重い方の障害等級を2級繰り上げる。",a:false,e:"則14条3項。13級以上が2以上なら1級繰上げ。2級繰上げは8級以上が2以上の場合。",topic:"障害等級の併合"},
{id:"X2-243",s:2,q:"給付基礎日額は、原則として、労働基準法第12条の平均賃金に相当する額であり、その算定の基礎となる賃金には臨時に支払われた賃金や3か月を超える期間ごとに支払われる賃金は含まれない。",a:true,e:"8条1項・労基法12条4項。賞与等は算入されず、特別支給金の算定基礎年額(特別給与)として別途考慮される。",topic:"給付基礎日額"},
{id:"X2-244",s:2,q:"障害(補償)等年金前払一時金が支給された場合には、障害(補償)等年金差額一時金の支給額の算定においても、支給済みの前払一時金の額が考慮される。",a:true,e:"58条1項。差額一時金は、支給済みの年金額と前払一時金の合計額が所定額に満たない場合の差額。",topic:"差額一時金"},
{id:"X2-245",s:2,q:"遺族(補償)等年金の受給権者である妻が再婚したときは、その者の受給権は消滅するが、その子が受給資格者であれば子に受給権が移る。",a:true,e:"16条の4。妻は婚姻で失権し、次順位の子(受給資格者)に転給する。",topic:"遺族(補償)等年金の失権"},
{id:"X2-246",s:2,q:"遺族(補償)等一時金の受給順位において、労働者の死亡当時その収入によって生計を維持していなかった父母は、生計を維持していた孫より先順位となる。",a:false,e:"16条の7第1項。生計維持していた子・父母・孫・祖父母が、生計維持していなかった子・父母・孫・祖父母より先順位。",topic:"遺族(補償)等一時金"},
{id:"X2-247",s:2,q:"年金たる保険給付を受ける権利が消滅した場合には、その期の支払期月でなくても、支払うべき年金が支払われる。",a:true,e:"9条3項ただし書。権利が消滅した場合等は支払期月でなくても支払う。",topic:"年金の支給期間"},
{id:"X2-248",s:2,q:"介護(補償)等給付は、老人福祉法に規定する特別養護老人ホームに入所している間も支給される。",a:false,e:"12条の8第4項・告示。特別養護老人ホーム等に入所している間は支給しない。",topic:"介護(補償)等給付"},
{id:"X2-249",s:2,q:"通勤災害の療養給付を受ける者が、療養開始後3日以内に死亡した等の理由で休業給付を受けない場合には、一部負担金は徴収されない。",a:true,e:"則44条の2。休業給付を受けない者からは一部負担金を徴収しない。",topic:"一部負担金"},
{id:"X2-250",s:2,q:"労働基準法上の労働者に該当しない者に対しては、特別加入の場合を除き、労災保険法による業務災害に関する保険給付は行われない。",a:true,e:"労災保険法の労働者は労基法9条の労働者と同義。事業主・一人親方等は33条の特別加入によってのみ保護される。",topic:"適用・労働者性"},
{id:"XT2-01",s:2,format:"choice",examFmt:true,topic:"適用事業・暫定任意適用事業",difficulty:2,q:"労災保険の適用に関する次の記述のうち、正しいものはどれか。",choices:[{t:"労働者派遣事業による派遣労働者に係る労災保険の適用事業は、派遣先の事業である。",ok:0,why:"通達。派遣労働者は派遣元事業主の事業が適用事業となる。"},{t:"国の直営事業にも、労災保険法が適用される。",ok:0,why:"3条2項。国の直営事業には適用されない。"},{t:"暫定任意適用事業の事業主は、その事業に使用される労働者の過半数が希望するときは、労災保険の加入の申請をしなければならない。",ok:1,why:"整備法5条。労働者の過半数が希望すれば事業主に加入申請義務が生じる。"},{t:"同居の親族のみを使用する事業において、その同居の親族は、原則として労災保険法上の労働者に該当する。",ok:0,why:"労基法116条2項。同居の親族のみを使用する事業は労基法の適用除外で、原則労働者に該当しない。"},{t:"暫定任意適用事業の保険関係の消滅の申請には、労働者の同意は不要である。",ok:0,why:"整備法8条。成立後1年経過に加え、労働者の過半数の同意が必要。"}],memoryPoint:"派遣は派遣元、暫定任意の加入は過半数希望で義務、脱退は1年経過+過半数同意。",trap:"派遣先・派遣元の入替え、脱退時の同意要件の有無が狙われる。"},
{id:"XT2-02",s:2,format:"choice",examFmt:true,topic:"特別加入",difficulty:3,q:"特別加入に関する次の記述のうち、誤っているものはどれか。",choices:[{t:"卸売業を営む事業主は、常時100人以下の労働者を使用する場合に中小事業主等として特別加入できる。",ok:0,why:"33条1号・則46条の16。卸売・サービス業100人以下。"},{t:"特別加入者に対しては、二次健康診断等給付は行われない。",ok:0,why:"特別加入者は一次健康診断の対象外のため、二次健康診断等給付は行われない。"},{t:"海外派遣者として特別加入できるのは、日本国内で行われる事業(有期事業を除く)から派遣される者である。",ok:0,why:"33条7号。現地採用者や有期事業からの派遣者は対象外。"},{t:"特別加入者にも、特別給与を算定基礎とする障害特別年金等のボーナス特別支給金が支給される。",ok:1,why:"特別支給金支給規則。特別加入者にはボーナス特別支給金は支給されない(一般の特別支給金は支給)。"},{t:"特別加入者の休業(補償)等給付は、所得喪失の有無にかかわらず、全部労働不能であることが要件とされる。",ok:0,why:"通達。特別加入者には賃金を受けない日という要件はない。"}],memoryPoint:"特別加入者には二次健診なし・ボーナス特別支給金なし。海外派遣は国内の継続事業から。",trap:"特別支給金には一般分とボーナス分があり、特別加入者は一般分だけ支給される点をぼかしてくる。"},
{id:"XT2-03",s:2,format:"choice",examFmt:true,topic:"業務上外の認定",difficulty:3,q:"業務災害の認定に関する次の記述のうち、正しいものはどれか。",choices:[{t:"地震などの天災地変による被災は、いかなる場合も業務上とされない。",ok:0,why:"通達。危険環境下で天災地変により被災しやすい事情があれば業務上とされうる。"},{t:"労働基準法施行規則別表第1の2に列挙されていない疾病は、業務上の疾病とはされない。",ok:0,why:"別表第1の2第11号「その他業務に起因することの明らかな疾病」がある。"},{t:"脳・心臓疾患の認定基準では、発症前2か月間ないし6か月間にわたり1か月当たりおおむね80時間を超える時間外労働が認められる場合、業務と発症との関連性が強いと評価される。",ok:1,why:"令和3年認定基準。1か月100時間超又は2〜6か月平均80時間超で関連性が強い。"},{t:"精神障害の労災認定では、発病前おおむね1年の間の業務による強い心理的負荷が要件とされる。",ok:0,why:"令和5年認定基準。評価期間は発病前おおむね6か月。"},{t:"業務による精神障害で正常な判断能力が著しく阻害された状態での自殺は、故意による死亡として保険給付の対象とならない。",ok:0,why:"12条の2の2第1項・通達。この場合の自殺は故意に該当しない。"}],memoryPoint:"脳心は1か月100h/2〜6か月平均80h、精神は発病前おおむね6か月。",trap:"80時間と100時間、6か月と1年の入替えが定番。"},
{id:"XT2-04",s:2,format:"choice",examFmt:true,topic:"通勤災害",difficulty:3,q:"通勤災害に関する次の記述のうち、誤っているものはどれか。",choices:[{t:"事業主が提供する専用の通勤バスによる出勤途上の事故は、業務災害として扱われる。",ok:0,why:"7条2項。業務の性質を有するものとして通勤から除かれる。"},{t:"退勤途中に病院で診察を受けることは、逸脱・中断の例外となる日常生活上必要な行為に該当する。",ok:0,why:"則8条4号。"},{t:"要介護状態にある配偶者の父母の介護(継続的又は反復して行われるもの)は、日常生活上必要な行為に該当する。",ok:0,why:"則8条5号。配偶者の父母も含まれる。"},{t:"住居と就業の場所との間に合理的な経路が複数ある場合、そのうち最短のもの1つに限り合理的な経路とされる。",ok:1,why:"7条2項・通達。通常利用しうる経路が複数あれば、いずれも合理的な経路。"},{t:"複数就業者の事業場間の移動中の災害は、移動先の事業場の保険関係で処理される。",ok:0,why:"7条2項2号・通達。移動先での労務提供のための移動として扱う。"}],memoryPoint:"専用バス・緊急呼出しは業務災害。合理的経路は複数ありうる。事業場間移動は移動先。",trap:"最短に限る、届出経路に限るという限定表現はほぼ誤り。"},
{id:"XT2-05",s:2,format:"choice",examFmt:true,topic:"給付基礎日額",difficulty:4,q:"給付基礎日額に関する次の記述のうち、正しいものはどれか。",choices:[{t:"給付基礎日額に1円未満の端数があるときは、これを切り捨てる。",ok:0,why:"8条の5。1円に切り上げる。"},{t:"休業給付基礎日額のスライド改定は、平均給与額が変動した四半期の翌四半期の初日以後の分から行われる。",ok:0,why:"8条の2第1項2号。翌々四半期の初日以後。"},{t:"年金給付基礎日額のスライド改定は、年度の平均給与額が100分の10を超えて変動した場合に限り行われる。",ok:0,why:"8条の3。年金は変動幅要件のない完全自動スライド。"},{t:"障害(補償)等一時金などの一時金の給付基礎日額には、年齢階層別の最低・最高限度額は適用されない。",ok:1,why:"8条の4。一時金にはスライドは準用されるが年齢階層別限度額は適用しない。"},{t:"休業給付基礎日額に係る年齢階層別限度額の年齢は、休業の初日における年齢による。",ok:0,why:"8条の2第2項。支給事由が生じた日の属する四半期の初日の年齢。"}],memoryPoint:"端数は切上げ、休業スライドは10%・翌々四半期、年金は完全自動・翌々年度8月、一時金に年齢限度額なし。",trap:"翌四半期と翌々四半期、切捨てと切上げの入替え。"},
{id:"XT2-06",s:2,format:"choice",examFmt:true,topic:"療養(補償)等給付・一部負担金",difficulty:3,q:"療養(補償)等給付に関する次の記述のうち、誤っているものはどれか。",choices:[{t:"療養の費用の支給は、療養の給付をすることが困難な場合のほか、療養の給付を受けないことに相当の理由がある場合に行われる。",ok:0,why:"13条3項・則11条の2。"},{t:"傷病(補償)等年金を受ける者にも、療養(補償)等給付は支給される。",ok:0,why:"18条2項で併給されないのは休業(補償)等給付のみ。"},{t:"業務災害により療養の給付を受ける労働者からも、一部負担金として200円が徴収される。",ok:1,why:"31条2項。一部負担金は通勤災害の療養給付に限られる。"},{t:"第三者の行為による通勤災害で療養給付を受ける者からは、一部負担金は徴収されない。",ok:0,why:"則44条の2。"},{t:"療養の費用を請求する権利は、費用を支出した日ごとにその翌日から起算して2年で時効消滅する。",ok:0,why:"42条・通達。"}],memoryPoint:"一部負担金は通勤災害だけ(200円、日雇特例100円)。療養は傷病年金と併給。",trap:"業務災害にも一部負担金があるかのように書く肢が典型。"},
{id:"XT2-07",s:2,format:"choice",examFmt:true,topic:"休業(補償)等給付",difficulty:3,q:"休業(補償)等給付に関する次の記述のうち、正しいものはどれか。",choices:[{t:"療養のため休業した日に年次有給休暇を取得して賃金を受けた場合も、休業(補償)等給付は支給される。",ok:0,why:"14条1項。賃金を受ける日となり支給されない。"},{t:"所定休日については、休業(補償)等給付は支給されない。",ok:0,why:"通達。所定休日も支給される。"},{t:"平均賃金の100分の60未満の金額しか受けない日は、賃金を受けない日に該当する。",ok:1,why:"通達。60%未満しか支払われない日は賃金を受けない日として扱う。"},{t:"複数業務要因災害による休業の場合も、待期3日間は各事業主が労基法上の休業補償を行わなければならない。",ok:0,why:"複数業務要因災害は個々の事業主の災害補償責任の対象外。"},{t:"休業特別支給金は、休業の初日から支給される。",ok:0,why:"特別支給金支給規則3条。第4日目から。"}],memoryPoint:"賃金60%未満の日は不支給にならない。所定休日も支給。休業特別支給金も第4日目から。",trap:"年休日・休日の扱いを逆にしてくる。"},
{id:"XT2-08",s:2,format:"choice",examFmt:true,topic:"傷病(補償)等年金",difficulty:3,q:"傷病(補償)等年金に関する次の記述のうち、誤っているものはどれか。",choices:[{t:"療養開始後1年6か月を経過した日又は同日後において、治らず傷病等級に該当する場合に支給される。",ok:0,why:"12条の8第3項。"},{t:"傷病(補償)等年金は、請求によらず所轄労働基準監督署長の職権で支給決定される。",ok:0,why:"12条の8第3項・施行規則。支給決定のため傷病の状態等に関する届を提出する。"},{t:"傷病等級第3級の傷病(補償)等年金の額は、給付基礎日額の245日分である。",ok:0,why:"別表第1。1級313、2級277、3級245日分。"},{t:"傷病(補償)等年金を受ける者には、休業(補償)等給付もあわせて支給される。",ok:1,why:"18条2項。傷病(補償)等年金を受ける者には休業(補償)等給付は行わない。"},{t:"傷病特別支給金の額は、傷病等級第1級の場合114万円である。",ok:0,why:"特別支給金支給規則5条の2。"}],memoryPoint:"傷病年金は職権・1年6か月・1〜3級(313/277/245)。休業とは併給しない、療養とは併給。",trap:"療養と休業のどちらが併給されないかを入れ替える。"},
{id:"XT2-09",s:2,format:"choice",examFmt:true,topic:"障害(補償)等給付",difficulty:3,q:"障害(補償)等給付に関する次の記述のうち、正しいものはどれか。",choices:[{t:"第8級以上に該当する身体障害が2以上ある場合には、重い方の障害等級を1級繰り上げる。",ok:0,why:"則14条3項。8級以上2以上は2級繰上げ。"},{t:"障害等級第7級の障害(補償)等年金の額は、給付基礎日額の131日分である。",ok:1,why:"別表第1。"},{t:"障害(補償)等年金前払一時金は、同一の事由について何回でも請求できる。",ok:0,why:"則附則。1回に限る。"},{t:"障害(補償)等年金差額一時金を受けることができる遺族は、労働者の死亡当時生計を維持されていた者に限られる。",ok:0,why:"58条。生計同一の配偶者等が第1順位、それ以外の配偶者等が第2順位。"},{t:"第5級以上に該当する身体障害が2以上ある場合には、重い方の障害等級を2級繰り上げる。",ok:0,why:"則14条3項。5級以上2以上は3級繰上げ。"}],memoryPoint:"併合繰上げは13級以上→1級、8級以上→2級、5級以上→3級。",trap:"繰上げ幅を1段ずらす肢が頻出。"},
{id:"XT2-10",s:2,format:"choice",examFmt:true,topic:"加重・併合・差額一時金",difficulty:4,q:"障害(補償)等給付に関する次の記述のうち、誤っているものはどれか。",choices:[{t:"既存障害が第8級(一時金)の者が加重により第7級(年金)となった場合、第7級の年金額から第8級の一時金の額を25で除した額を差し引いた額の年金が支給される。",ok:0,why:"則14条5項。"},{t:"障害等級第1級の障害(補償)等年金差額一時金の基準額は、給付基礎日額の1,340日分である。",ok:0,why:"58条・附則。"},{t:"障害(補償)等年金差額一時金を受ける権利は、5年で時効消滅する。",ok:0,why:"42条。障害(補償)等給付に属し5年。"},{t:"障害(補償)等年金前払一時金は、年金の支給決定の通知のあった日の翌日から1年以内であれば、年金の請求後でも請求できる。",ok:0,why:"則附則。"},{t:"第9級と第13級の障害を併合して第8級とする場合には、第8級の一時金である給付基礎日額の503日分がそのまま支給される。",ok:1,why:"則14条3項ただし書。9級391+13級101=492日分が上限となる。"}],memoryPoint:"併合繰上げで一時金合算額を超えるときは合算額。加重で既存が一時金なら25で割る。",trap:"503日分をそのまま支給と書く肢は、ただし書を知らないと正解に見える。"},
{id:"XT2-11",s:2,format:"choice",examFmt:true,topic:"遺族(補償)等年金の受給資格",difficulty:3,q:"遺族(補償)等年金の受給資格者に関する次の記述のうち、正しいものはどれか。",choices:[{t:"夫は、労働者の死亡当時60歳以上でなければ受給資格者とならない。",ok:0,why:"附則43条。55歳以上60歳未満の夫も受給資格者となり、60歳まで支給停止。"},{t:"子は、労働者の死亡当時20歳未満であれば受給資格者となる。",ok:0,why:"16条の2。18歳に達する日以後の最初の3月31日までの間。"},{t:"労働者の死亡当時胎児であった子が出生したときは、将来に向かって、その子は生計を維持していた子とみなされる。",ok:1,why:"16条の2第2項。"},{t:"共働きの妻は、労働者の収入によって生計を維持していたことにならない。",ok:0,why:"通達。一部でも生計を維持されていれば足りる。"},{t:"兄弟姉妹は、年齢や障害の有無にかかわらず受給資格者となる。",ok:0,why:"16条の2。18歳年度末まで、55歳以上又は障害要件が必要。"}],memoryPoint:"妻は無条件、夫・父母・祖父母は55歳以上(60歳まで若年停止)、子・孫は18歳年度末。胎児は出生時から将来に向かって。",trap:"20歳・60歳と数字をずらす肢、共働きは不可とする肢に注意。"},
{id:"XT2-12",s:2,format:"choice",examFmt:true,topic:"遺族(補償)等年金の額・失権",difficulty:3,q:"遺族(補償)等年金に関する次の記述のうち、誤っているものはどれか。",choices:[{t:"遺族が1人の場合の年金額は、原則として給付基礎日額の153日分である。",ok:0,why:"別表第1。55歳以上等の妻は175日分。"},{t:"遺族が4人以上の場合の年金額は、給付基礎日額の245日分である。",ok:0,why:"別表第1。"},{t:"受給権者が直系姻族の養子となった場合には、受給権は消滅しない。",ok:0,why:"16条の4第1項3号。直系血族・直系姻族以外の養子となったときに失権。"},{t:"受給権者が届出をしていない事実上の婚姻をした場合には、受給権は消滅しない。",ok:1,why:"16条の4第1項2号。婚姻には事実婚を含み、失権する。"},{t:"受給権者の所在が1年以上明らかでない場合には、同順位者等の申請により所在不明の間支給が停止される。",ok:0,why:"16条の5。"}],memoryPoint:"153/201/223/245(妻55歳以上等1人は175)。事実婚も失権、直系姻族の養子は失権しない。",trap:"事実婚の扱いを逆にする肢が定番。"},
{id:"XT2-13",s:2,format:"choice",examFmt:true,topic:"遺族(補償)等一時金・前払一時金",difficulty:4,q:"遺族(補償)等給付に関する次の記述のうち、正しいものはどれか。",choices:[{t:"遺族(補償)等一時金の第1順位は、労働者の死亡当時生計を維持されていた子である。",ok:0,why:"16条の7。第1順位は配偶者。"},{t:"遺族(補償)等年金前払一時金の最高額は、給付基礎日額の1,340日分である。",ok:0,why:"60条・附則。最高額は1,000日分。"},{t:"年金の受給権者が全員失権し他に受給資格者がない場合で、支給済みの年金と前払一時金の合計額が給付基礎日額の1,000日分に満たないときは、その差額が遺族(補償)等一時金として支給される。",ok:1,why:"16条の6第1項2号。"},{t:"遺族特別支給金は、受給権者が2人以上あるときは、それぞれに300万円ずつ支給される。",ok:0,why:"特別支給金支給規則5条。300万円を人数で等分。"},{t:"遺族(補償)等一時金について、生計を維持されていた兄弟姉妹は配偶者に次ぐ順位となる。",ok:0,why:"16条の7。兄弟姉妹は生計維持の有無を問わず最後順位。"}],memoryPoint:"一時金の順位は配偶者→生計維持の子父母孫祖父母→非生計維持の子父母孫祖父母→兄弟姉妹。前払は最高1,000日分。",trap:"障害の前払一時金(1級1,340日分)と数字を混ぜてくる。"},
{id:"XT2-14",s:2,format:"choice",examFmt:true,topic:"介護(補償)等給付",difficulty:3,q:"介護(補償)等給付に関する次の記述のうち、誤っているものはどれか。",choices:[{t:"障害(補償)等年金又は傷病(補償)等年金の受給権者が対象となる。",ok:0,why:"12条の8第4項。一時金受給者は対象外。"},{t:"病院又は診療所に入院している間は支給されない。",ok:0,why:"12条の8第4項。"},{t:"障害等級第3級の障害(補償)等年金の受給権者は対象とならない。",ok:0,why:"施行規則(別表第3)。1級と2級の一部に限る。"},{t:"介護を受け始めた月において介護費用を支出していない場合でも、その月について最低保障額が支給される。",ok:1,why:"施行規則。初月は費用を支出した場合のみ支給され、最低保障額の適用はない。"},{t:"傷病(補償)等年金の受給権者は、その支給決定を受けた後に介護(補償)等給付を請求する。",ok:0,why:"施行規則。"}],memoryPoint:"対象は年金受給者の1級と2級(精神神経・胸腹部臓器)。入院・施設入所中は不支給。初月は実費のみ。",trap:"初月の最低保障額の有無を逆にする肢がひっかけ。"},
{id:"XT2-15",s:2,format:"choice",examFmt:true,topic:"二次健康診断等給付",difficulty:3,q:"二次健康診断等給付に関する次の記述のうち、正しいものはどれか。",choices:[{t:"特別加入者も、一次健康診断で異常の所見があれば二次健康診断等給付を受けることができる。",ok:0,why:"特別加入者には二次健康診断等給付は行われない。"},{t:"二次健康診断等給付の請求は、原則として一次健康診断を受けた日から3か月以内に行わなければならない。",ok:1,why:"施行規則。"},{t:"特定保健指導は、医師のみが行う。",ok:0,why:"26条2項2号。医師又は保健師。"},{t:"二次健康診断は、1年度につき2回まで行われる。",ok:0,why:"26条2項。1年度につき1回。"},{t:"二次健康診断等給付は、業務災害に関する保険給付の一種である。",ok:0,why:"7条1項4号。独立した保険給付。"}],memoryPoint:"請求は一次健診受診日から3か月以内。二次健診は1年度1回、特定保健指導は医師又は保健師。",trap:"保健師を外す、回数を増やす、特別加入者を含めるの3パターン。"},
{id:"XT2-16",s:2,format:"choice",examFmt:true,topic:"年金の支給期間・未支給・内払",difficulty:3,q:"保険給付の通則に関する次の記述のうち、誤っているものはどれか。",choices:[{t:"年金たる保険給付は、支給すべき事由が生じた月の翌月から始め、権利が消滅した月で終わる。",ok:0,why:"9条1項。"},{t:"年金たる保険給付は、毎年2月・4月・6月・8月・10月・12月の6期に、それぞれ前月分までが支払われる。",ok:0,why:"9条3項。"},{t:"受給権者が死亡した場合の未支給の保険給付は、死亡当時生計を同じくしていた配偶者、子、父母、孫、祖父母又は兄弟姉妹が請求できる。",ok:0,why:"11条1項。"},{t:"未支給の遺族(補償)等年金は、死亡した受給権者と生計を同じくしていた者であれば、次順位の遺族以外の者も請求できる。",ok:1,why:"11条1項かっこ書。遺族(補償)等年金の未支給分は次順位者等の遺族が請求する。"},{t:"同一傷病で休業(補償)等給付から傷病(補償)等年金に切り替わった後に支払われた休業(補償)等給付は、年金の内払とみなされる。",ok:0,why:"12条2項。"}],memoryPoint:"年金は翌月から消滅月まで、偶数月6期払い。未支給の遺族年金は次順位の遺族。",trap:"未支給の請求者の範囲を広げる肢に注意。"},
{id:"XT2-17",s:2,format:"choice",examFmt:true,topic:"支給制限・費用徴収",difficulty:4,q:"支給制限及び費用徴収に関する次の記述のうち、正しいものはどれか。",choices:[{t:"重大な過失による事故の場合、休業(補償)等給付等はその額の100分の50が減額される。",ok:0,why:"12条の2の2第2項・通達。100分の30。"},{t:"重大な過失による支給制限の対象には、療養(補償)等給付も含まれる。",ok:0,why:"通達。療養(補償)等給付は対象外。"},{t:"事業主が重大な過失により保険関係成立届を提出していない期間中の事故について保険給付を行った場合、保険給付額の100分の40が徴収される。",ok:1,why:"31条1項1号・通達。故意は100%、重大な過失は40%。"},{t:"事業主が故意又は重大な過失により生じさせた業務災害については、保険給付額の100分の40が徴収される。",ok:0,why:"31条1項3号・通達。100分の30。"},{t:"特別支給金も、事業主からの費用徴収の対象となる。",ok:0,why:"31条1項。対象は保険給付で、特別支給金は含まれない。"}],memoryPoint:"未手続:故意100%・重過失40%、滞納:滞納率(上限40%)、事業主の故意重過失災害:30%。労働者の重過失:30%減。",trap:"30%と40%の入替えが最頻出。"},
{id:"XT2-18",s:2,format:"choice",examFmt:true,topic:"社会復帰促進等事業・特別支給金",difficulty:3,q:"社会復帰促進等事業に関する次の記述のうち、誤っているものはどれか。",choices:[{t:"社会復帰促進等事業は、社会復帰促進事業、被災労働者等援護事業及び安全衛生確保等事業からなる。",ok:0,why:"29条1項。"},{t:"賃金の支払の確保を図るために必要な事業は、社会復帰促進等事業に含まれる。",ok:0,why:"29条1項3号。"},{t:"特別支給金は保険給付ではないため、事業主の損害賠償額から控除することはできない。",ok:0,why:"最判平8.2.23(コック食品事件)。"},{t:"休業特別支給金の支給の申請は、休業した日の翌日から起算して5年以内に行えばよい。",ok:1,why:"特別支給金支給規則3条。2年以内。"},{t:"ボーナス特別支給金の算定基礎日額は、算定基礎年額を365で除して得た額である。",ok:0,why:"特別支給金支給規則6条。"}],memoryPoint:"特別支給金の申請期限は休業2年、障害・遺族・傷病5年。損害賠償からは控除されない。",trap:"申請期限の2年と5年を入れ替える。"},
{id:"XT2-19",s:2,format:"choice",examFmt:true,topic:"不服申立て・時効",difficulty:3,q:"不服申立て及び時効に関する次の記述のうち、正しいものはどれか。",choices:[{t:"審査請求は、処分があった日の翌日から起算して60日以内にしなければならない。",ok:0,why:"労働保険審査官及び労働保険審査会法8条。知った日の翌日から3か月以内。"},{t:"保険給付に関する処分の取消しの訴えは、再審査請求の裁決を経た後でなければ提起できない。",ok:0,why:"40条。審査請求の決定を経れば足りる。"},{t:"審査請求をした日から3か月を経過しても決定がないときは、審査官が審査請求を棄却したものとみなすことができる。",ok:1,why:"38条2項。"},{t:"葬祭料(葬祭給付)を受ける権利は、5年で時効消滅する。",ok:0,why:"42条。2年。"},{t:"労働者災害補償保険審査官は、厚生労働省本省にのみ置かれる。",ok:0,why:"労働保険審査官及び労働保険審査会法2条。都道府県労働局に置かれる。"}],memoryPoint:"審査請求3か月、再審査請求2か月、3か月決定なしで棄却みなし。取消訴訟は審査請求前置のみ。",trap:"平成28年改正前の再審査請求前置を正しいと思わせる肢。"},
{id:"XT2-20",s:2,format:"choice",examFmt:true,topic:"併給調整・複数業務要因災害",difficulty:4,q:"労災保険法に関する次の記述のうち、誤っているものはどれか。",choices:[{t:"同一事由で障害厚生年金及び障害基礎年金が支給される場合、障害(補償)等年金の調整率は0.73である。",ok:0,why:"別表第1。"},{t:"同一事由で遺族厚生年金及び遺族基礎年金が支給される場合、遺族(補償)等年金の調整率は0.80である。",ok:0,why:"別表第1。"},{t:"社会保険の年金との併給調整では、労災保険の年金の側が減額される。",ok:0,why:"別表第1。社会保険の年金は全額支給。"},{t:"複数業務要因災害に関する保険給付の名称には「補償」の文字が付く。",ok:1,why:"20条の2以下。複数事業労働者療養給付等と呼び、補償は付かない。"},{t:"複数事業労働者とは、事業主が同一人でない2以上の事業に使用される労働者をいう。",ok:0,why:"1条。"}],memoryPoint:"調整率は障害0.73/0.83/0.88、遺族0.80/0.84/0.88。減るのは労災側。複数業務要因災害は補償なし。",trap:"障害と遺族の調整率の入替え、補償の2文字の有無。"},
{id:"XS2-1",s:2,format:"sentaku",sentaku:true,topic:"給付基礎日額・スライド",difficulty:3,q:"【選択式】給付基礎日額 ─ 本文の空欄A〜Eに入る語句を、下の選択肢から選べ。",passage:"給付基礎日額は、労働基準法第12条の[[A]]に相当する額とする。休業補償給付に係る休業給付基礎日額は、四半期ごとの平均給与額が、算定事由発生日の属する四半期の平均給与額の100分の[[B]]を超え、又は100分の90を下回るに至った場合には、その上昇し又は低下するに至った四半期の[[C]]の初日以後に支給すべき事由が生じた休業補償給付について改定される。また、休業補償給付を支給すべき事由が生じた日が療養を開始した日から起算して[[D]]を経過した日以後の日である場合には、年齢階層別の最低限度額及び最高限度額が適用される。なお、給付基礎日額に1円未満の端数があるときは、これを[[E]]。",blanks:[{key:"A",ok:6,why:"8条1項。給付基礎日額は労基法12条の平均賃金に相当する額。",law:"8条1項"},{key:"B",ok:13,why:"8条の2第1項2号。上下10%を超える変動で改定。",law:"8条の2第1項"},{key:"C",ok:17,why:"8条の2第1項2号。変動した四半期の翌々四半期の初日以後。",law:"8条の2第1項"},{key:"D",ok:0,why:"8条の2第2項。休業は療養開始後1年6か月経過日以後から年齢階層別限度額を適用。",law:"8条の2第2項"},{key:"E",ok:16,why:"8条の5。1円未満は1円に切り上げる。",law:"8条の5"}],options:["1年6か月","四捨五入する","賃金日額","105","翌々年度の8月","10円に切り上げる","平均賃金","標準報酬日額","翌年度","切り捨てる","3年","6か月","翌四半期","110","1年","基本手当日額","1円に切り上げる","翌々四半期","120","115"],memoryPoint:"平均賃金・110/90・翌々四半期・1年6か月・切上げ。",trap:"翌四半期と翌々四半期、年金の翌々年度8月との混同を誘う。"},
{id:"XS2-2",s:2,format:"sentaku",sentaku:true,topic:"障害(補償)等給付・差額一時金",difficulty:3,q:"【選択式】障害補償給付 ─ 本文の空欄A〜Eに入る語句を、下の選択肢から選べ。",passage:"障害補償給付は、厚生労働省令で定める障害等級に応じ、障害補償年金又は障害補償一時金とし、障害等級第1級から第[[A]]級までは年金、それより下位の等級は一時金とされる。第13級以上に該当する身体障害が2以上あるときは、原則として重い方の身体障害の障害等級を[[B]]繰り上げる。障害補償年金を受ける権利を有する者が死亡した場合において、既に支給された障害補償年金の額及び障害補償年金前払一時金の額の合計額が障害等級に応じて定める額に満たないときは、その差額に相当する額の[[C]]をその遺族に支給する。この遺族の第1順位は、労働者の死亡の当時その者と[[D]]配偶者、子、父母、孫、祖父母及び兄弟姉妹であり、障害等級第1級の場合の基準となる額は給付基礎日額の[[E]]である。",blanks:[{key:"A",ok:1,why:"15条・別表第1。1〜7級は年金、8〜14級は一時金。",law:"15条"},{key:"B",ok:16,why:"則14条3項。13級以上2以上は1級、8級以上は2級、5級以上は3級繰上げ。",law:"則14条3項"},{key:"C",ok:13,why:"附則58条1項。年金受給権者死亡時の差額を支給する一時金。",law:"附則58条1項"},{key:"D",ok:15,why:"附則58条2項。第1順位は生計を同じくしていた配偶者等(生計維持要件ではない)。",law:"附則58条2項"},{key:"E",ok:12,why:"附則58条1項。1級1,340日分〜7級560日分。",law:"附則58条1項"}],options:["560日分","7","同居していた","313日分","生計を維持していた","1,000日分","障害補償年金前払一時金","2級","14","8","扶養していた","3級","1,340日分","障害補償年金差額一時金","障害補償一時金","生計を同じくしていた","1級","5","1,190日分","障害特別支給金"],memoryPoint:"年金は7級まで。13級以上2以上で1級繰上げ。差額一時金の遺族は生計同一、1級1,340日分。",trap:"生計維持(遺族年金)と生計同一(差額一時金・未支給)の書き分けが狙われる。"},
{id:"XS2-3",s:2,format:"sentaku",sentaku:true,topic:"遺族(補償)等年金の受給資格・失権",difficulty:3,q:"【選択式】遺族補償年金 ─ 本文の空欄A〜Eに入る語句を、下の選択肢から選べ。",passage:"遺族補償年金を受けることができる遺族は、労働者の配偶者、子、父母、孫、祖父母及び兄弟姉妹であって、労働者の死亡の当時その収入によって[[A]]ものとする。ただし、妻以外の者にあっては、本則上、夫、父母又は祖父母については[[B]]歳以上であること、子又は孫については18歳に達する日以後の最初の3月31日までの間にあること等の要件を満たすことを要する。労働者の死亡の当時胎児であった子が出生したときは、[[C]]、その子は、労働者の死亡の当時その収入によって生計を維持していた子とみなす。受給権者が直系血族又は[[D]]以外の者の養子となったときは、その受給権は消滅する。また、受給権者の所在が[[E]]以上明らかでない場合には、同順位者があるときは同順位者の、同順位者がないときは次順位者の申請によって、その所在が明らかでない間、その支給を停止する。",blanks:[{key:"A",ok:8,why:"16条の2第1項。遺族(補償)等年金は生計維持要件。",law:"16条の2第1項"},{key:"B",ok:10,why:"16条の2第1項1号。本則は60歳以上。附則43条で55歳以上60歳未満も受給資格者とされ60歳まで支給停止。",law:"16条の2第1項"},{key:"C",ok:19,why:"16条の2第2項。胎児は出生の時から将来に向かって受給資格者となる。",law:"16条の2第2項"},{key:"D",ok:3,why:"16条の4第1項3号。直系血族・直系姻族の養子となっても失権しない。",law:"16条の4第1項"},{key:"E",ok:5,why:"16条の5第1項。所在不明1年以上で支給停止。",law:"16条の5第1項"}],options:["65","請求の時から","2年","直系姻族","労働者の死亡の時にさかのぼって","1年","配偶者","6か月","生計を維持していた","扶養されていた","60","生計を同じくしていた","50","三親等内の親族","同居していた","55","出生の時にさかのぼって","傍系血族","3か月","将来に向かって"],memoryPoint:"生計維持・本則60歳(附則で55歳)・将来に向かって・直系姻族・所在不明1年。",trap:"本則の60歳と附則の55歳のどちらを問うているかが要注意。"},
{id:"XS2-4",s:2,format:"sentaku",sentaku:true,topic:"二次健康診断等給付",difficulty:3,q:"【選択式】二次健康診断等給付 ─ 本文の空欄A〜Eに入る語句を、下の選択肢から選べ。",passage:"二次健康診断等給付は、労働安全衛生法の規定による健康診断等のうち直近のもの(一次健康診断)において、血圧検査、血液検査その他業務上の事由による[[A]]及び心臓疾患の発生にかかわる身体の状態に関する検査であって厚生労働省令で定めるものが行われた場合に、当該検査を受けた労働者がそのいずれの項目にも異常の所見があると診断されたときに、当該労働者(一次健康診断の結果その他の事情により既にこれらの疾患の症状を有すると認められるものを除く。)に対し、その請求に基づいて行う。二次健康診断は[[B]]につき1回に限り行われ、特定保健指導は、二次健康診断の結果に基づき、医師又は[[C]]による面接によって行われる。二次健康診断等給付の請求は、原則として一次健康診断を受けた日から[[D]]以内に行わなければならない。なお、二次健康診断等給付は[[E]]には行われない。",blanks:[{key:"A",ok:0,why:"26条1項。脳血管疾患及び心臓疾患の発生にかかわる検査。",law:"26条1項"},{key:"B",ok:4,why:"26条2項1号。二次健康診断は1年度につき1回。",law:"26条2項1号"},{key:"C",ok:8,why:"26条2項2号。特定保健指導は医師又は保健師の面接。",law:"26条2項2号"},{key:"D",ok:3,why:"施行規則。一次健康診断を受けた日から3か月以内に請求。",law:"施行規則"},{key:"E",ok:1,why:"特別加入者は一次健康診断の対象外のため行われない。",law:"34条等"}],options:["脳血管疾患","特別加入者","精神疾患","3か月","1年度","2年度","1年","1か月","保健師","腎疾患","派遣労働者","1暦年","半年","2か月","肝疾患","日雇労働者","看護師","短時間労働者","管理栄養士","産業カウンセラー"],memoryPoint:"脳血管疾患・心臓疾患、1年度1回、医師又は保健師、3か月以内、特別加入者は対象外。",trap:"1年度と1暦年、保健師と看護師の入替え。"},
{id:"XS2-5",s:2,format:"sentaku",sentaku:true,topic:"介護(補償)等給付・年金の支給期間",difficulty:3,q:"【選択式】介護補償給付 ─ 本文の空欄A〜Eに入る語句を、下の選択肢から選べ。",passage:"介護補償給付は、障害補償年金又は[[A]]を受ける権利を有する労働者が、その受ける権利を有する年金の支給事由となる障害であって厚生労働省令で定める程度のものにより、常時又は随時介護を要する状態にあり、かつ、常時又は随時介護を受けているときに、当該介護を受けている間(障害者支援施設に入所して生活介護を受けている間、病院又は診療所に[[B]]している間等を除く。)、当該労働者に対し、その請求に基づいて行う。介護補償給付は、[[C]]を単位として支給する。また、年金たる保険給付の支給は、支給すべき事由が生じた月の[[D]]から始め、支給を受ける権利が消滅した月で終わるものとし、毎年2月、4月、6月、8月、10月及び12月の6期に、それぞれその[[E]]までを支払う。",blanks:[{key:"A",ok:13,why:"12条の8第4項。障害補償年金又は傷病補償年金の受給権者が対象。",law:"12条の8第4項"},{key:"B",ok:9,why:"12条の8第4項。病院又は診療所に入院している間は支給しない。",law:"12条の8第4項"},{key:"C",ok:17,why:"19条の2。介護補償給付は月を単位として支給。",law:"19条の2"},{key:"D",ok:1,why:"9条1項。支給事由が生じた月の翌月から。",law:"9条1項"},{key:"E",ok:3,why:"9条3項。偶数月の6期に、それぞれ前月分までを支払う。",law:"9条3項"}],options:["休業補償給付","翌月","四半期","前月分","日","障害補償一時金","遺族補償年金","当月","週","入院","通院","在宅","当月分","傷病補償年金","翌々月","前々月分","入所","月","翌月分","前月"],memoryPoint:"介護は年金受給者だけ・入院中不支給・月単位。年金は翌月から消滅月まで、偶数月に前月分まで。",trap:"一時金受給者を対象に含める、当月からと書くなどの入替え。"},
{id:"XS2-6",s:2,format:"sentaku",sentaku:true,topic:"不服申立て・支給制限",difficulty:3,q:"【選択式】不服申立て・支給制限 ─ 本文の空欄A〜Eに入る語句を、下の選択肢から選べ。",passage:"保険給付に関する決定に不服のある者は、[[A]]に対して審査請求をし、その決定に不服のある者は、労働保険審査会に対して再審査請求をすることができる。審査請求をしている者は、審査請求をした日から[[B]]を経過しても審査請求についての決定がないときは、審査官が審査請求を棄却したものとみなすことができる。審査請求及び再審査請求は、時効の完成猶予及び更新に関しては、これを[[C]]とみなす。また、労働者が故意の犯罪行為若しくは[[D]]により、又は正当な理由がなくて療養に関する指示に従わないことにより、負傷、疾病、障害若しくは死亡若しくはこれらの原因となった事故を生じさせ、又は負傷、疾病若しくは障害の程度を増進させ、若しくはその回復を妨げたときは、政府は、保険給付の[[E]]を行わないことができる。",blanks:[{key:"A",ok:18,why:"38条1項。審査請求先は労働者災害補償保険審査官。",law:"38条1項"},{key:"B",ok:9,why:"38条2項。3か月決定がなければ棄却とみなせる。",law:"38条2項"},{key:"C",ok:16,why:"38条3項。裁判上の請求とみなす。",law:"38条3項"},{key:"D",ok:0,why:"12条の2の2第2項。故意の犯罪行為若しくは重大な過失。",law:"12条の2の2第2項"},{key:"E",ok:8,why:"12条の2の2第2項。全部又は一部を行わないことができる(故意は1項で行わない)。",law:"12条の2の2第2項"}],options:["重大な過失","不注意","請求の放棄","厚生労働大臣","6か月","2か月","60日","3割","全部又は一部","3か月","催告","全部","過失","都道府県労働局長","一部","故意","裁判上の請求","承認","労働者災害補償保険審査官","労働基準監督署長"],memoryPoint:"審査官→審査会、3か月で棄却みなし、裁判上の請求。重大な過失・療養指示違反は全部又は一部。",trap:"故意(1項・行わない)と故意の犯罪行為・重過失(2項・全部又は一部)の区別。"}
);
